if not text then
    text = { values = {}, templates = {} }
    addon.worldText.speech = text
end
local rows = text.values
rows["32:746375885"]="도와줘요, 누군가"
rows["32:74791098"]="이제 노란 걸 추가하기만 하면..."
rows["32:749451292"]="불의 영이 우리에게 지혜를 주옵소서"
rows["32:754930883"]="이 전쟁은 이길 수 없어"
rows["32:757811342"]="물러서!"
rows["32:760769765"]="발자국 조심해... 무하하!"
rows["32:760775390"]="이제 화를 내세워줘"
rows["32:764744441"]="크리스마스에 몇 개 가 될지 말해"
rows["32:766223139"]="배를 찾아서 돌아와!"
rows["32:767501166"]="응급 전력 저장소 온라인"
rows["32:768947400"]="좀 더 망칠 시간이야!"
rows["32:769380922"]="어쩌면... 크록, 네가 옳았을지도."
rows["32:769838946"]="난 내 도전 카드를 사용하고 싶어요!"
rows["32:772334712"]="지금 내 시간을 낭비하고 있어!"
rows["32:778807733"]="너의 의지가 너를 배반한다."
rows["32:782853851"]="%s는 믿지 않고 머리를 흔들고 있습니다."
rows["32:784039893"]="여기서 우리가 우리의 입장을 제시할 것입니다!"
rows["32:784113057"]="악마가 너무 많고 시간이 부족해"
rows["32:795595730"]=" ⁇ 을 내려놔, 친구들!"
rows["32:795642392"]="네조트의 의지가 당신을 부패시킵니다."
rows["32:795691379"]="TugofWar 버프봇, 호드 인사"
rows["32:803081937"]="호드 전쟁 기계가 당신을 필요로 합니다!"
rows["32:805042812"]=" ⁇ 말레일, 비밀만 말해줘!"
rows["32:811056932"]="제플린이 6분 안에 도착할 겁니다"
rows["32:814059153"]="어떻게 여기까지 올랐어요?"
rows["32:818654746"]="불타는 군단이 너희 모두를 파멸시키리라!"
rows["32:820985985"]="겨울의 홀로 이동해"
rows["32:824090548"]="내겐 아름다운 꽃이?"
rows["32:82707852"]="하, 새끼 양이 잔뜩 몰려오는구나!"
rows["32:82858631"]="%s는 설치류 크레이트를 샀어!"
rows["32:829152797"]="장교, 스파이글라스를 빌려주세요"
rows["32:831688385"]="네 비참한 방어는 여기서 끝납니다!"
rows["32:833327867"]="너희 부자 똥구리들은 모두 똑같다!"
rows["32:83417485"]="이쪽은 꽤나 좋지 않은 상태입니다."
rows["32:840179391"]="%s는 울음성 크리스탈을 불러옵니다!"
rows["32:843339680"]="아우레론, 좀 도와줘요"
rows["32:84378444"]="버드에 대해 뭐라고 할 수 있어?"
rows["32:84415883"]="더 많은 영들이 더 많아요!"
rows["32:848705128"]="시간은 금이라네, 친구. 어서 가보게!"
rows["32:853454095"]="이 땅은 우리..."
rows["32:854761101"]="아이스윙 벙커를 누가 통제하는가?"
rows["32:856183694"]="꿈꾸는 자는 절대로 깨울 수 없다!"
rows["32:859523908"]="날 하늘을 올려다봐, 사시!"
rows["32:860077315"]="이단자들! 성스러운 칼을 받아라!"
rows["32:860572556"]=" ⁇ 은 눈앞에 서서 의문을 품고 있습니다!"
rows["32:864590896"]="하지만, 정말일까요? 이 검이..."
rows["32:875295964"]="난 너희 시체를 화살시킬 거야!"
rows["32:876290632"]="그건 별 차이가 없을거야"
rows["32:877057799"]="당신의 믿음은 승리로 인도해 주죠"
rows["32:877108130"]="뭐, 쇼비즈니스 그만둬야 돼?"
rows["32:878606519"]="뭔가 냄새가 났다고 생각했어요"
rows["32:882623766"]="조심해,  ⁇ 을 불태우지 마"
rows["32:888100846"]="난 임자가 있는 몸이야! 저리 꺼져!"
rows["32:89101903"]="난 사냥꾼이고 훈련하고 싶어"
rows["32:892075625"]="폭풍의 힘은 죽지 않는다."
rows["32:892423795"]="더 이상 만나고 싶지 않아!"
rows["32:905396903"]="크아아아아! 너 해치우러 왔다!"
rows["32:905844752"]="호드를 포기한다면"
rows["32:907434838"]="이런 결말을 바라진 않았다!"
rows["32:909835200"]="리코가 아이디어를 가졌어"
rows["32:910325769"]="함께 무쇠 드워프와 싸웁시다!"
rows["32:911285498"]="해마르는 촉각에 따뜻합니다."
rows["32:912291969"]="하루 종일 기다렸어!"
rows["32:917761616"]="너희와 달리 나는 다재다능하다!"
rows["32:924927290"]="그래, 사촌. 하지만... 마을"
rows["32:925315578"]="걱정할만한 한 가지 더 적은 이교도"
rows["32:927324105"]="바삭바삭 벌레는 너무 맛나. 좀 줄까?"
rows["32:928917967"]="데 다크스피어는 절대 포기하지 않을 거야!"
rows["32:931482063"]="고마워, 여기서 나 갈 수 있어"
rows["32:932970399"]="%s 발레에 탐욕적으로 쥐고"
rows["32:933949433"]="윈터엑스의 지혜를 내게 주시오!"
rows["32:936207600"]="포털 에너지 중심을 파괴해!"
rows["32:940016495"]="그 제이드 마녀는 정말 무서운 거잖아"
rows["32:940652482"]="끝은 여기야, 이제 끝이야!"
rows["32:941777496"]="이 보잘것없는 마을을 짓밟아 버려라!"
rows["32:941780802"]="난 화재로 죽고 싶지 않아"
rows["32:9503443"]="이 침입에 대해 돈을 지불할 거야!"
rows["32:950845245"]="%s의 유적이 땅에 떨어집니다."
rows["32:951146560"]="도망쳐! 검은무쇠 드워프다!"
rows["32:953698235"]="우리의 적들은 멸망당할 것이다!"
rows["32:956747636"]="%s 나무에서 사과를 잡습니다."
rows["32:962183537"]="스컬지 하수도에서 도와줘요"
rows["32:964341145"]="백두산을 넣으세요."
rows["32:965823637"]="이 곳은 정말 뜨겁습니다!"
rows["32:969331697"]="영혼의 향연이 시작되리라..."
rows["32:972874069"]="사야 할 물건이 너무 많아요"
rows["32:974919287"]="이봐! 우리 보물에서 손 떼라고!"
rows["32:975911473"]="좋아, 나 가요 소리 그만해요"
rows["32:978029304"]="마냥 서 있기만 하려니 힘들지 않나?"
rows["32:980733683"]="<고등왕 다리온 모그라인 이끄는 것>"
rows["32:981121479"]="내가 여기 죽게 될 줄 알았어"
rows["32:981578498"]="좋아, 포기해..."
rows["32:986518859"]="이 비밀은 당신과 함께 죽을 거야"
rows["32:986630240"]="이 개똥들이 우리 맥주를 훔쳐가고 있어!"
rows["32:987094374"]="도망갈 곳이 없어 겁쟁이!"
rows["32:989213497"]="자, 구름날개야. 한 바퀴 돌아보자꾸나."
rows["32:993703647"]="%s은 눈에 띄는 문서를 떨어뜨립니다."
rows["32:994083648"]="고엘, 내가 널 잃었다고 생각했어"
rows["32:99618305"]="소문이 사실인 거요"
rows["32:996801048"]="날 피하지 못해, 필사자!"
rows["330:1512838114"]="세계 끝 타버나는 내 종류 를 제공하는 것 은 아무것도 없습니다. 하지만, 저는 이 곳 은 내 판매 할 것 이 관심 있는 고객층 을 끌어들이는 것 을 알게 되었습니다.$B$B저는 먼 곳에서 구입되는 이국적인 공학 상품에 전문적이어서 가끔은 드물게 한두 가지 물건을 구입할 수도 있습니다.$B$B내가 뭘 하고 싶은가?"
rows["330:165066055"]="검색 중... 제1관리자 활동 정지는 행성 시스템의 오류를 알리는 첫 번째 신호로 간주됩니다. 이에 따라 관찰자 알갈론의 실체가 도착하여 행성 진단을 실행합니다. 도출될 수 있는 응답 신호는 두 가지로서, 응답 코드 알파는 \"모두 정상\" 신호, 응답 코드 오메가는 행성 재창조 신호입니다."
rows["330:306042037"]="그들의 명백한 형태는 전쟁의 시대로부터 약해졌고, 그들이 직접 창조한 세계 아래 갇혀있었고, 타이탄 형식의 부패는 표면을 통해 퍼져서 구 신들을 괴롭혔습니다.$B$B그 때 그리고 그 곳에서 형제들이 돌아갔어요. 5천 년 동안 이 세계의 중심에서 전투가 벌어졌습니다.\010"
rows["330:408078387"]="불쾌한 곳, 이 \"언더시티 \"은 전혀 옛 로데론와 같지 않습니다.$b$b만약 당신이 스트라톨메로 가고 싶다면, 나는 지금 당장 도움을 줄 수 없지 두려워합니다. 불타는 도시 근처의 탑은 여전히 논쟁에 있으며, 따라서 나의 힘은 당신을 도울 수 없을 정도로 약해졌습니다."
rows["330:670559814"]="우리 집 은 대폭탄 때 파괴 되었다!$B$B생존자들은 북쪽으로 가서 로르다넬을 건설했지만, 남은 사람들은 이 곳에 있는 이유는 있습니다.$B$B그 동안 그들을 처리하는 데 도움이 되길 바랍니다."
rows["331:1757035190"]="두려움 은 우리 의 가장 큰 무기 이었습니다. 모든 전쟁 은 두려움 과 의심 의 변하는 어깨 에 달려 승리 하고 패배 를 당해 왔습니다. 그렇다면 두려움 이 없는 적 을 어떻게 싸워야 합니까?$B$B<사우르펀그는 머리를 흔들고 있습니다.>$B$B우리는 단지 스컬지 이 노스렌드우리가 우리의 감각을 통제하기 위해 싸우고,\010"
rows["331:1882548789"]="브리즈트!$B$B매트릭스 펀코그래프에 오신 것을 환영합니다 3005 A 스트로크, 보안 레벨 알파 터미널$B$B터미널 기능에 접근하기 위해 흰색 펀치 카드를 가져야 합니다.\01001000100 01101111 01110111 01101110 00100000 01110111 01101001 01110100 01101000 00100000 01110100 01101000 01100101 00100000 01101000 01101111 01110010 01100100 01100101 00100001"
rows["331:2140215488"]="보강, 마침내! 감옥 경비자들은 더 오래 이 침략을 견딜 수 없습니다! 당신은 내 사람들을 풀어 내기 위해 최선을 다해야 합니다. 방어 시스템에는 여전히 약간의 힘이 있습니다. 감옥 주변에 있는 활성화 크리스탈을 사용하여 상황이 악화되면 방출을 유발합니다."
rows["331:562710595"]="우리들 중 한 명입니다. 우리들의 숫자가 너무 빠르게 증가하는 것을 보고 기쁘습니다.$B$B그 멍청한 트롤은 내가 마녀들의 이미지를 깨끗하게 하고 우리가 그의 종인 걸 증명하기 위해 열심히 일한다고 생각해요 불타는 군단 이 세상이 완전히 소실되면"
rows["332:1529121165"]="브랜, 럿거, 나와 원숭이 사이가 더 이상 이상한 거잖아 38 다른 언어들, 티탄의 한 가지 부분을 포함해서 - 바니르와 에시르 모두.$B$B어쨌든, 그녀가 누르면서 박수를 하는 것은 누구도 \"자재\"하지 않았죠."
rows["332:1547013753"]="천천히, 내가 그 자리에 올거야!$B$B그래서 저거였어, 누가 나타나면 피를 흘리고, 내장도 흘려서?$B$B다크 아이언스, 내가 한 마디도 안 들었어?$B$B암흑철자는 블랙록 오크보다 조금 더 현명한 놈들이야 300 - 미안해"
rows["332:1694010751"]="저 악마들은 우리를 파멸의 구렁텅이에 빠뜨리고자 하나 필시 우리가 이길 수 없는 상대라 여길 것이오. 저들 자신을 파멸로 몰고 가는 건 우리요. 우리 연합이 카자크와 그의 군대를 처치할 것이오. 그리하려면 그들이 세상을 멸망시키려는 야욕에 못지않게 우리는 몸과 마음을 불사르려는 각오를 다져야 하오."
rows["332:1830829031"]="아주 오래전, 이 세계가 태초의 모습을 간직하고 있던 때 바로 이 땅에서 티탄과 무시무시한 힘을 가진 사악한 존재 사이에 싸움이 있었죠. 예언서에는 티탄이 이겼는지 패했는지에 대해서 정확하게 나와 있지 않지만, 티탄이 전사한 것으로 기록되어 있어요. 한 명의 티탄 또한 전사한 것으로 되어 있죠. 아니면 그렇게 생각되는 것일 수도 있고..."
rows["332:25582015"]="아니, 내가 알 수 있는 건 아니죠. 주로 지역에 따라 달라진 것 같습니다. 어떤 인종들은 그들을 슬림, 어떤  ⁇ 이라고 표명했습니다.$B$B제가 매번  ⁇ 이나 슬림, 또는 침을 접할 때마다 그들은 기본적으로 같은 생물들이었습니다. 그 차이점은 환경에 따라 달라지기 때문일 것 같습니다. 그래서 우리는 순수한 샘플을 필요로 합니다."
rows["332:410585737"]="물론 모든 것이 불꽃을 피우고 거대한 헬륨 폭탄처럼 폭발하는 위험은 없습니다. 이 아기가 당신을 언더시티 어떤 배 보다 더 빠르고 안전 한 곳 이 되고, 그 시야 는 정말 참신한 곳 이다. 호흡 에 관해 말 할 때, 제펠린 에 탑승 하는 동안 흡연 을 허용 하지 못하며, 여행 중 불꽃 마술 을 던지는 것 은 금지 되어 있다."
rows["332:86103021"]="그래서... 끔찍한 죽음에서 구출된 후 불평하는 것을 싫어하긴 하지만 난 아직도 여기 엉뚱한 교두방에 갇혀있다는 걸 알아야 한다고 생각했어요. 그리고 정말 멋진 일이겠죠, 만약 당신이 와서 저를 밖으로 내보내면"
rows["332:866779046"]="내 아들이 여기 있다는 이야기를 들었습니다. 그는 이제 리치 왕의 봉사에서 강력한 죽음의 기사입니다. 이것이 사실이라면, 혈통을 끝내는 것은 내가어야 합니다.$B$B이제 제 임무는 오그림의 해머를 아이스크로wn 성탑 꼭대기에 올려놓고 모든 것을 파괴하는 것입니다 스컬지 당신이랑 동맹들이 준비되면 떠나죠"
rows["332:954899596"]="만약 내 사랑하는 형제들이 지금 이 순간 나와 함께 있었더라면, 그들은 이 발견이 얼마나 큰 것인지 믿지 않았을 것입니다.$B$B법원은 이 방에 보관된 타이탄 디스크의 도서관 관리자입니다.$B$B바닥 아래의 디스크를 볼 수 있어 서둘러야 돼 왜니의 가장 위대한 발견이 바로 앞에 있어요"
rows["333:1069348747"]="내 조력자야$B$B물론 우리처럼 괴롭혀진 게 아니었지만, 여전히 괴롭혀진 게 분명해 실바나스에게 무릎을 꿇어 있어$b$b그리고 우리 둘 사이에... 솔직히 말해서, 암흑여부가 그녀가 방으로 들어갔을 때 이미 무릎을 꿇고 있다고 생각했지!"
rows["333:1084295765"]="노인 틸은 오' 보물 가득한 동굴을 발견!!!!$B$B금과 다이아몬드, 자메트, 조각상, 책으로 가득한 방!$B$B그 동굴을 돌아다니면서 하루가 지났고, 그는 기근에 빠졌습니다.$B$B그래서 그가 왔던 곳으로 돌아갔고 무슨 일이 있었는지도 몰랐지만"
rows["333:1095185267"]="일단 기기를 만들면, 그냥 Toshley's Station에 운반될 수 있도록 기기를 활성화시켜야 합니다. 몇 명의 사람들이 닭으로 변신했다고 보고했지만, 저는 그들이 과장했다는 것을 확신합니다!\010가능하다면 다른 사람이 사용할 때 기기를 사용하지 않으려고 노력하겠지만, 당신이 할지라도 잘 될 것입니다!"
rows["333:1445838793"]="제 동생은 이 무역로로 큰 돈을 벌 수 있다고 말했지만, 저 쪽에 사는 사람이 될 것이라고 말하지 않았습니다. 제펠린에 타고 이쪽으로 돌아와면, 먹을 것을 가져오실 수 있나요? 오그리마에서 가장 좋은 고기를 팔고 있는데,"
rows["333:1915993178"]="불타는 칼의 씨가 무너진 후, 우리는 우리들, 래의 지배로부터 우리 자신과 우리 사람들을 해방시키기로 맹세했습니다.$B$B이 일은 가능하지만, 제 명예는 여전히 불만족입니다.$B$B저는 호드 내가 전투에서 영광스럽게 죽을 때까지 다른 전사들을 훈련시켜야 한다$B$B훈련 준비 됐어?"
rows["333:2037420588"]=" ⁇ 은들은 마침내 탑의 상단에 이르는 문을 무너뜨리는데 성공했습니다. 우리 마지도 성당 내 3가지 장벽 중 첫 번째 장벽을 성공적으로 비활성화했습니다.$B$B$4939W일 안에 크림슨 홀의 장벽이 열릴 수 있어야 합니다.\010"
rows["333:2063227588"]="예, 예, 이 모든 것이 매우 흥미롭습니다. 하지만 여기서 볼 수 있듯이 우리는 우리의 생명을 위해 싸우고 있습니다. 그리고 이 피그미들은 그 동굴 안에 있는 것과 비교해 우리의 가장 작은 문제입니다!$B$B내가 가장 필요한 때 비참한 비서님이 어디 있어요?"
rows["333:481930529"]="바시르의 크리스탈 포크를 사용하여 당신의 위축 조각들을 마법사의 불안정한 플럭으로 변형시킬 수 있습니다. 이 플럭들은 음주자를 더 지능적이고 더 심혈을 기울이고, 그들의 해로운 마법과 치유의 효과를 높여줍니다.$B$B하지만, 한  ⁇ 을 구입할 수 있는 10개의 덩어리가 없어진 것 같습니다."
rows["334:1413926152"]="리야리아가 새로운 포털사이트를 만들고 싶어? 그 여자는 미친다.$b$b발드린의 연구에서는 그런 함정을 피할 수 있는 방법이 있다고 제안했고$b$b충분한 시간을 줘서 캠프에 다른 포털을 불러낼 수 있을지도 몰라"
rows["334:1725963287"]="로어워커들은 세계를 여행하며 새로운 이야기를 발견하고 오래된 이야기를 재고합니다.$B$B우리는 판다리아의 장소와 사람들의 풍부한 역사를 탐구합니다.$B$B이 이야기들 중 일부를 직접 듣고 싶다면, 영원한 꽃의 계곡에 있는 모고'산 궁전 입구 위에 있는 지식의 자리에서 로리워커 쇼와 이야기하십시오."
rows["334:178075515"]="그들은 우리를 알지 못해 모든 고원을 한꺼번에 공격했고, 땅에서 폭발하고, 공중에서 날아오르고, 대부분의 그리폰 날개가 흩어져 있었고, 너무 많은 좋은 왜들이 목숨을 잃었습니다.$B$B키건이 우리를 함께 하지 않았다면 희망은 거의 없었을 겁니다. 그 사람에게 목숨을 빚어졌어요. 적어도 이제 우리는 기회를 가질 수 있습니다."
rows["334:293935707"]="마지막으로 손가락을 귀에 넣으면 뇌가 5개 커질 거야$B$B그래서 암흑철자들은 그의 목숨을 구하고 그를 포로로 데려갔고, 그들의 지도자는, 타우리스라는 자존심하고 거만한 사람이 아이언포를 자기로 데려갔고, 그 때엔 마지막엔 윈저를 봤어요.\010"
rows["334:45610752"]="30 레벨에서는 두 개의 클래스 전문화, 재능 및 글립 세트를 활성화하여 쉽게 전환할 수 있는 이중 전문화를 배울 수 있습니다.\010또한 각 세트마다 별도의 글리프 패널과 액션 바를 갖게 될 것입니다.\010전투에서 두 세트를 전환하는 것은 불가능하며, 사용 가능한 자원을 소비할 것입니다."
rows["334:72593517"]="브루페스트 기념품 좀 가져오세요. 우리는 전통적인 휴일 옷부터 맛있는 맥주 미니 케이크까지 모두 가지고 있습니다. Blix Fixwidget에 얘기만 해 주세요."
rows["334:960839051"]="래티온은 마지막 살아있는 검은 용이라고 주장하고 있어요 아웃랜드 어딘가?$b$b어쨌든, 그는 매력적이라고 생각합니다. 그는 내가 만난 다른 용과 같지 않습니다. 그는 정직하고 거의 고통스럽습니다. 나는 그가 필사적인 생명을 절대적으로 귀중하거나 완전히 낭비할 수 있다고 생각하는지 결정할 수 없습니다."
rows["335:1305721734"]="벤처기업에서 기술을 빌려서 연구력을 강화할 수 있다고 생각했습니다. 보시다시피, 그들의 새로운 셔더는$B$B제 사업 파트너인 위즈클랭크는 여기 서쪽에서 스러드 Fen에 있습니다. 저한테 '필드 리서치'를 하고 있지만 아직 돌아오지 않았습니다. "
rows["335:1800788938"]="모두 와! 다크월 페어에 오신 것을 환영합니다. 모험을 갈망하십니까? 이국적이고 신비로운 보물을 찾고 있습니까? 더 이상 찾지 마십시오. 당신은, 내 친구, 올바른 장소에 왔습니다! 바로 잠수하고 페어의 제공하는 모든 것에 참여하십시오. 우리는이 장소에서 일주일 내내있을 것입니다. 그래서 당신의 친구와 사랑하는 사람들에게 확실히 말하십시오!"
rows["335:92315243"]="마우아리의 캐시에는 위대한 비밀이 있습니다. 그 반사적인 조각들이 사용되는데, 그 반사적인 표면을 이용해 다른 물건으로부터 힘을 끌어내고$B$B매력을 적재로 보관하면, 전투하는 짐승들로부터 에코, 영적 힘을 수집할 수 있습니다."
rows["335:980020372"]="내가 아는 것보다 더 많은 철강의 비밀을 알고 있는 것 같네요. 그건 좋죠. 왜냐하면 그것은 가져가야 하기 때문입니다. 이제 당신은 인간 땅 남쪽의 정글로 가야 합니다."
rows["335:991336675"]="물은 생명을 옮기는 것 뿐이야 내 번역이 이제 이해가 되고$b$b모가들은 수감자와 반란자들과 노예를 희생함으로써 그들의 삶을 물로 길게 만들었을 것이라고 생각합니다.$b$b또한 제가 연구하고 있던 모든 고대 서적들은 모가 본래 쓴 것으로 추정하고 그 사실을 언급하지 않았다고 생각합니다."
rows["336:141722673"]="내가 원하는 것은 창조자들이 울덤 복합에 접근할 수 있도록 하는 것입니다.$B$B현재 디스크 세트에는 Uldum의 플레이트가 포함되어 있지 않습니다. 입력의 주요 조건은 Uldum의 플레이트가 존재하는 경우만 액세스 할 수 없습니다."
rows["336:1662217139"]="서쪽으로 가는 걸 보면 내 외딴 아버지를 찾아봐$b$B저는 우리가 \"원래성을 만들어내는 것\"을 듣고 자랐습니다. 그는 꽤 맥주를 좋아하는 사람이죠.$b$B하지만, 그가 가진 장품이나 이야기가 흥미롭다고 생각할 수도 있습니다."
rows["336:1750681715"]="스태그헬름, 이곳을 떠나기 전에 마지막으로 그대에게 줄 것이 하나 있소. 만약 그대가 이 저주받은 요새에 다시 들어와야 할 때가 오거든 흐르는 모래의 홀로 신성한 징을 울리시오. 그러면 보호막을 유지하고 있는 마력이 사라지고, 이 세계에 다시 한 번 안퀴라즈의 공포가 찾아올 것이오."
rows["336:1871312101"]="가장 겸손한 사과, 챔피언, 하지만 당신은 위대한 십자군 재판을 완료 할 수있는 기회가 부족했습니다. 상기하기 위해, 당신과 당신의 동료 모험가들은 매주 한 번 위대한 십자군 시험에 시작할 수 있습니다. 스컬지!"
rows["336:1934310681"]="바로 그 때... 아칸이트 부이 하나를 만들고 바다에 올려 놓아야 합니다. 나의 미노우는 마법의 발현에 끌려가게 될 것입니다. 그가 부이 근처에 도착하면 - BLAMO! 그것은 미노우의 진정한 형태를 드러내는 신비한 에너지의 영광스러운 충동으로 폭발할 것입니다. 또한, 당신은 네프톨론의 분노를 당하거나 당하지 않을 수도 있습니다. 50/50 우연한 기회라고 할 수 있습니다."
rows["336:1947550218"]="우리 는 일 년 에 한 번 다른 마을 으로 여행 하여 무역 을 하게 되었으며, 우리 모두 이 생활 을 즐겨 했다.$B$B지금, 전쟁의 반향이 우리 주위에서 울리고 있습니다. 우리는 이 곤란한 시간을 조심스럽게 항해해야 합니다."
rows["336:27204489"]="니비, 바보, 방해하지 마! 난 네 뼈의 고기를 찢고 네 뼈골을 코트 랙으로 사용하겠다. 이제 내가 어디 있었을까? 오, 그래, 그래서 크로시우스는 평범한 지옥보다 거의 10배 더 오래 살았어. 나는 왜인지 확실하지 않지만 충분한 연구로, 나는 알아낼 수 있다고 확신한다.$B$B크로시우스의 지옥핵을 되찾아야 해"
rows["337:1063216512"]="왜 우리는 거북이야? 산 페리야. 경로의 포장자야. 산을 가로질러 안내하는 사람야.$b$b우리는 벽을 지키는 사람들을 먹여주는 사람들이고, 모고 왕조 시절부터 버랩 트레일을 여행하는 사람들입니다.$b$b우리는 또한 행운을 향하기 위해 가장 좋은 코를 가지고 있습니다!"
rows["337:1098909397"]="브루페스트는 완벽한 휴일이지만 한 가지 문제 있어요.$b$b공격자들은 무료 맥주 양념을 제공하는 배들을 겨냥하고$b$b만약 당신이 여기 있다면, 암흑철왜성이 나타나면, 도움을 주고,"
rows["337:1281485501"]="오멘은 엘루네라 호수의 깊숙한 곳에 잠들지만, 스톰레이지 바로우 덩어리 근처의 동남쪽 해안에서 소환될 수도 있습니다.$B$B발사체에 로켓을 넣으면 오멘의 부하들이 올 거야, 더 많은 로켓을 발사해봐, 거의 3두잔이나 엘뉴의 촛불을 그의 부하들에게 발사해줘"
rows["337:562768245"]="전 아론소스 사당에서 만나겠습니다. 그것은 빛의 전달자 우더가 은손으로 성직된 곳입니다. 스컬지이 만지지 않는 유일한 건물이며, 도시의 그 절반에 우리의 최전선 운영 기지 될 것입니다. 당신의 도움으로, 스트라톨메는 빛의 수도와 로데론의 새로운 시작이 될 것입니다."
rows["338:1129496039"]="두려워하지 마세요. 우리는 여러분을 돕기 위해 여기 있습니다. 우리는 여러분이 우리의 옛 집 안에서 우리에게 주신 방어에 감사하고, 그리고 감사의 표정으로, 우리가 왔는데, 여러분이 필요하면 빨리 전염병 땅으로 돌아가도록 도와줍니다."
rows["338:1550542392"]="듀로 관리소는 태프스트 킨에 가장 가까운 시설이기 때문에 대부분의 짐을 처리합니다.$B$B이 강간을 과부하하는 것은 파이프라인에서 누출을 일으킨다. 발출되는 에너지는 원치 않는 마나 생물들을 끌어들이고 있습니다. 우리는 많은 누출 장소에서 마나 생물 침투를 겪었습니다. Manaforge Duro는 현재 가장 많이 영향을 받고 있습니다."
rows["338:1682105079"]="우리는 크로스의 육신에서 태어났고 그의 고기와 뼈로부터 만들어졌습니다.$b$b크로시크는 크로스의 피입니다. 그는 우리를 지켜보고 있습니다. 그는 크로스와 우리의 연결고리입니다. 그는 크로스의 힘을 가지고 있지만, 그는 우리의 세계를 걷습니다.$b$b시간이 되면 크로시크가 죽고, 우리는 그의 힘을 빼앗아 다시 시작될 것이다."
rows["338:2109279741"]="바로스 클라우드스트라이더와 그의 반지 보호자들은 두 번째 반지를 보호합니다. 당신의 드레크는 반지 보호자들에게 더 많은 일치하지만 바로스는 오클루스의 에너지로부터 만들어진 непроницаемых 방패 뒤에 있습니다."
rows["338:357701139"]="인정하고 싶지 않지만 곰이 날 이기게 됐어$b$b하지만, 만약 당신이 그 곰을 죽일 수 있다면, 자랑스러운 업적이 될 것입니다.$b$b<그분은 뒤에서 박수를 치고>$b$b곰이 가장 좋은 놈이니까 우린 널 파스트라이더 로지의 정규 멤버로 받아들일 거야"
rows["338:598332096"]="제가 지구 어머니와 호드에 봉사하기 위해 살아가면서, 우리가 필요한 모든 것을 수집한 지금 조금 긴장감을 느끼지 않을 수 없습니다. 적어도 얼라이언스이 모집 노력을 완료할 때까지는 약간의 시간이 있습니다. 그 후에 모든 것이 실리투스의 센라리오 포드에 배송 될 것이고 전쟁이 곧 이어질 것입니다."
rows["338:61146211"]="이 곳 은 한때 큰 비극 이 있었던 곳 이라고 느낄 수 있습니다. 이 곳 에서 죽음 이 고통 을 받고 있는 것 은 지금도 그 곳 에서 울림 을 내리고 있습니다.$B$B우리 세상에 침입한 이 침입을 완전히 봉쇄하려면 먼저 완전히 열어야 합니다.$B$B준비됐어?"
rows["339:1482868331"]="저는 준비품이 실리투스로 보내지고 있고, 모두 $2113w일 이내에 도착해야 한다고 들었습니다. 그 곤충들 중 하나가 내 광산에 들어가게 되는 것을 보고 싶지 않습니다. 그래서 누군가가 이 시트르를 집어넣는 시간을 갖고 있는 것으로 기대합니다."
rows["339:1703803337"]="단지 3 이 세상 사람들은 경쟁자, 고객, 직원입니다. 경쟁자들은 무자비하게 굴복하고, 고객들은 감히 받아들여지고, 직원들은 엄격히 감시되어야 합니다.$B$B독립 계약자는 신화입니다. 그들은 직원보다 더 나은 돈을 받고 싶어하지만 고객처럼 대접을 받습니다."
rows["339:1843979519"]="네싱워리 사파리의 일원이자, 우리는 온천 공기를 타고 이 땅을 건너가 버그를 지나가고 있었습니다.$b$b네싱워리와 그의 아들은 북쪽에서 발톱동물과 다른 동물들을 사냥하고 싶어했습니다.$b$b진짜 짐승들이 있는 숲에서 그들을 선발하기로 결정했습니다.$b$b로켓 타면 난 호랑이들 속에 갇혀 있어"
rows["339:1960531301"]="구제 의 무기는 우리 가장 경건한 기사들이 입었지 - 빛의 수반자 자신만큼은 무기가!$B$B수천 명이 마지막 전쟁에서 죽었고, 그들의 의복은 시체로부터 벗겨져 낙스라마스의 무서운 성으로 끌려갔다.$B$B낙스라마스의 죽음의 기사들이 자기들 자신의 용도로 구제판 우편을 부패시킨다고 한다.$B$B참사... "
rows["339:2025257608"]="아이세라라는 들어본 적 없어? 수호자 자연의 모습? 꿈의 모습? 그녀는 모든 녹색 용들의 대모입니다! 예, 이세라 자신은 내 왕국을 그녀의 새끼와 선물했습니다. 우리는 귀족 생물과 어깨를 나란히 했습니다. 그들은 우리에게 그들을 타고 적에 맞서 싸우도록 허락했습니다. 모든 것이 많은 세기에 걸쳐서 잘되었습니다..."
rows["339:555281660"]="네더가르드는 수년 동안 어두운 포털을 감시해왔고, 항상 깨어있었고, 우리는 긴 폐쇄된 게이트웨이에서$B$B우리는 전 세계 경보를 일으켰고, 세계는 응답했습니다.$B$B이제, 아르헨티나 Dawn은 호드와 얼라이언스의 왕국과 부족들이 그들의 군대를 모아 우리를 돕기 위해 달려가면서 이 선을 지키고 있습니다!"
rows["339:691650181"]="아래의 보블린 오일인1더벨트에서 요구되는 것을 사용하여  ⁇ 을 열십시오!$B|TInterface\\Icons\\INV_Misc_EngGizmos_20.blp:64|t |TInterface\\Icons\\INV_Misc_Bomb_07.blp:64|t |TInterface\\Icons\\INV_Misc_Ear_NightElf_02.blp:64|t |TInterface\\Icons\\INV_Misc_EngGizmos_swissArmy.blp:64|t |TInterface\\Icons\\INV_Weapon_ShortBlade_21.blp:64|t"
