rows["33:813210746"]="당신들 속임수를 사줄래?"
rows["33:815430439"]="항상 힘은 스컬블레이드에게!"
rows["33:8157114"]="다시 낡은 양철통 신세로구나!"
rows["33:817408915"]="이 정도 속도를 본 적 없어"
rows["33:817472733"]="시장은 오늘 바쁜 것 같네요"
rows["33:818735960"]="언젠가 레젝은 위대한 전사가 될 거야"
rows["33:819290025"]="이제 이 속임수가 그만해"
rows["33:823053429"]="부패를 없애고 싶으세요?"
rows["33:825592248"]="도와줘 열쇠를 찾아"
rows["33:825655470"]="언젠가는...복수해줄 테다."
rows["33:831697317"]="치 치에 대한 깃털?"
rows["33:832619276"]="너희의 피로 내 마법진을 칠하리라!"
rows["33:832808597"]="난 무기를 벗고 싶었어!"
rows["33:836360548"]="다들 준비해"
rows["33:837021652"]="동료들과 토론해 보도록 하겠습니다."
rows["33:840428738"]="이 트롤은 정말 더러운 놈이었어"
rows["33:844109627"]="큰 혀를 죽여, 노예!"
rows["33:846432609"]="내 부녀들을 복수하러 왔어!"
rows["33:848580781"]="록맨들이 파고들거나, 더 많은 타격을 주면!"
rows["33:849042830"]=" ⁇ 이 준비됐어, 적가 다가오고 있어!"
rows["33:851325783"]="우리는 비극적인 패배를 당했습니다."
rows["33:851355312"]="어떻게 톤크 도전을 할 수 있을까요?"
rows["33:852536520"]="치 치는 선물을 좋아해요"
rows["33:856113768"]="데라크 나이트폴, 당신들의 서비스로!"
rows["33:857214335"]="그리고 그것을 사용하여 얼라이언스을 죽여라!"
rows["33:85913176"]="넌 아주 끈질긴 시체야"
rows["33:85921613"]="크리스탈 리스터러는 어디서 찾을 수 있을까요?"
rows["33:863928528"]="어두움이 다가오고 두려움에 떨고"
rows["33:864238159"]="악! 제발 그만 뿌려!"
rows["33:867788277"]="맛을 본다면 좋겠소!"
rows["33:867968806"]="드디어 좋은 그룹을 봤어요!"
rows["33:868902368"]="진짜 호드는 막을 수 없습니다!"
rows["33:868985523"]="오크, 배드랜드, 난 무해!"
rows["33:869709115"]="아마 무리를 위한 먹거리로!"
rows["33:871547986"]="랭크 7-8 보스들의 기록을 참조하십시오."
rows["33:876160545"]="내가 태블릿을 방어할 수 있도록 도와줄게"
rows["33:876738172"]="그녀의 힘은 정말 끔찍합니다!"
rows["33:877937009"]="왜 계속 같은 길로 가는 거예요?"
rows["33:878005945"]="자네만 준비되면 우리는 언제든지 싸울 수 있네."
rows["33:878119303"]="아하하... 아쉽게 약해졌어요!"
rows["33:878241402"]="현재 요청하신 내용은 처리가 불가능합니다."
rows["33:881843626"]="케어 다로우에 오신 것을 환영합니다."
rows["33:885599500"]="축복의 갑판에 대해 말해줘"
rows["33:889876777"]="타타이, 제발. 우린 여기 손님이야."
rows["33:892820370"]="방해할 수 없소!"
rows["33:893310123"]="우리는 참으로 큰 고통을 당했습니다."
rows["33:896485278"]="새로운 농장들을 위한 또 다른 노예!"
rows["33:899433681"]="Loremaster의 색을 잃었어"
rows["33:90217051"]="뒤에서 뭔가 소리가 들립니다!"
rows["33:903553066"]="<코보크가 당신을 걱정으로 바라보고 있습니다.>"
rows["33:904210888"]="생명주님, 도와주세요!"
rows["33:905652427"]="움직였다고! 맹세해. 분명 움직이는 걸 봤어!"
rows["33:909803466"]="맛있는 양 냄새가 나네요"
rows["33:911891264"]="나는 준비되어 있습니다, 역사학자 아케소노스"
rows["33:917205995"]="내가 테스트할 수 있는 물건이 있나요?"
rows["33:91899531"]="고통은 너한테  ⁇ 을 거야"
rows["33:921788945"]="어떻게 침식 농작물을 돌볼까요?"
rows["33:923824998"]="트롤식 술래잡기를 할 시간이군요, 친구!"
rows["33:923992874"]="개구리 몇 개를 죽여보자, 블랑스!"
rows["33:925469876"]="%s는 통제할 수 없을 정도로 울기 시작합니다!"
rows["33:925552957"]="넌 영원히 갇혀 있을 거야!"
rows["33:927095709"]="%s 독한 칼을 잡으세요!"
rows["33:927602670"]="난 아무것도 듣지 않았어 맹세하네"
rows["33:92820396"]="감염된 짐승을 또 처치했습니다!"
rows["33:931218879"]="스위스, 오늘 화염이  ⁇ 어요"
rows["33:932052717"]="그 이야기를 다시 말해줘, 마르텍"
rows["33:936772051"]="얼굴에 가!"
rows["33:941831293"]="그래,  ⁇ 보르는 정말 나쁜 물건이야"
rows["33:943967166"]="한 삼오플랑이 이 모든 것을 통치할 수 있어!"
rows["33:948579280"]="키스는 정말 감사할 것 같아요"
rows["33:949477215"]="%s은 미소로 페이지에게 쳐다보며"
rows["33:951368953"]="썬더 블러프로 비행기를 타고 가자고"
rows["33:951526675"]="쉬이... 이제 다 끝이다."
rows["33:958687938"]="사피론이 공중으로 떠오릅니다!"
rows["33:960738704"]="낚시왕 선발대회를 시작합니다!"
rows["33:968934079"]="이쪽으로는 안 휘어지는 모양인데!"
rows["33:968934092"]="그렇게 구부리면 안 되나 보네."
rows["33:971957958"]="가구 내 양을 데려와"
rows["33:973061456"]="왜 이렇게 분홍색이고 털이 없는가?"
rows["33:98066453"]="축하의 시간은 끝났어"
rows["33:981440430"]="이곳을 깨끗이 정화하겠다!"
rows["33:984689161"]="죽음의 선구자가 새로 태어났군..."
rows["33:984729314"]="내 분노로 하늘도 불타고 있어요!"
rows["33:986160938"]="약간의 페인트만 있으면 괜찮아!"
rows["33:986465906"]="두려움의 얼굴을 보여드리겠습니다."
rows["33:986475153"]="*허프* 숨을 쉬어야 해..."
rows["33:987085506"]="가마솥이 계속 끓습니다..."
rows["33:992120332"]="오, 아니, 네! 지금 시작이야!"
rows["33:993671718"]="이제 이 조각들을 달궈 볼까..."
rows["33:996019423"]="난 도전을 기대했지"
rows["33:998384128"]="접근 직업 자동판매기"
rows["33:999974137"]="내가 만지지 않았어!"
rows["340:1103272225"]="포세이큰에 대한 최고의 말 을 왕실 의 약국 협회 의 이름으로 여러분 에게 제공 하는 것 을 기쁘게 생각합니다. 이 동물 들 은 우리 모두 처럼 시험 과 고난 을 견디고 있으며, 이제 그 들 도 단순한 필사적 인 육체가 될 운명 보다 더 강력 하고 더 탄력적 으로 나타났습니다."
rows["340:1943656702"]="그래서 다이아몬트에 호소했으니, 네 죽음을 참아야 한다고 명령받았어.$B$B우리가 처음 이야기했던 것을 잊지 마세요. 여러분께 제가 한 믿음은  ⁇ 니다. 여러분에게는 많은 증거가 있습니다.$B$B넌 떠나면 좋을 거야 내 발이 떨어지는 곳을 조심하는 게 피곤해"
rows["340:436511501"]="저는 부패로 인해 영향을 받은 식물 종류 가 4 가지 를 관찰 하였습니다. 노래 꽃, 바람 꽃, 윙어 뿌리, 밤 드래곤 식물. 노래 꽃과 바람 꽃은 펠우드 에서 흔히 볼 수 있는 식물 이며, 윙어 뿌리 와 밤 드래곤 은 덜 자주 볼 수 있습니다. 모두 펠우드 의 생태계의 중요한 부분 입니다."
rows["340:461711853"]="스컬지 내 직업의 남자 들 이 자기 적을 사냥하고 죽이는 이천적인 능력 을 연구 하고 자랑 한다. 나 자신 은 이 세상 을 구하기 위해 제 십자군 전쟁 에서 수천 개의 짐승 을 죽였습니다.$B$B저는 그 비참한 성격 때문에 암호 악마를 싫어하지만, 그 능력은 존경할 수 밖에 없습니다."
rows["341:2061012517"]="마지막 준비가 실리투스로 보내지고 하루도 안되는 것으로 전해졌는데, 그 곤충들이 내 광산에 들어가서 보기를 원하지 않으려고 합니다. 그래서 누군가가 이 모래의  ⁇ 을 집어넣어"
rows["341:2114140236"]="스톰윈드에 오신 것을 환영합니다! 저는 도시 공무원 중 한 명입니다. 인구조사 사무소를 통해 도시의 시민들에게 도움을 주고 있습니다. 만약 여러분이 특정 사람을 찾아야 한다면, 저는 여러분에게 도움을 줄 수 있을지도 모릅니다. 미묘한 방법과 날카로운 정신적 징계로, 저는 이 기록에 접근할 수 있습니다.$B$B만약 당신이 나와 함께 일을 하고 있다면, 제발 계속해 나가세요!"
rows["341:2117247836"]="그놈은 그들을 쫓아다니고, 널 보내서 도움을 요청했어?$B$B<아주루고스는 먼 거리에 눈을 뜨고, 그의 얼굴에 치아있는 미소가  ⁇ 니다.>$B$B내가 그를 구해준다면, 그는 내 딸들 중 한 명으로 만들지 않을 거야$B$B안나라, 미안해"
rows["341:31031107"]="아나서론의 패배는 아키모데의 목표에서 지연을 가져왔고, 승리를 훨씬 더 가까이 다가왔다. 하지만 내 군대는 여기서 남아 있을 수 없다."
rows["341:770597306"]="미트릴 케이스는 없어서 다  ⁇ 어요.$B$B미트릴 가죽은 문명에서 찾기 어렵지 않습니다. 기술력이 있는 엔지니어에게 물어보세요. 몇 개의 미트릴 바가 필요하다고 생각합니다. 하지만, 당신이 나를 도울 수 있다면, 나는 당신이 잘 보상받을 수 있는지 확인 할 것입니다!"
rows["341:968217739"]="스트라톨메는 재건되고 완전히 깨끗하게 되기까지는 꽤 오랜 시간이 걸릴 수도 있지만, 이 노력은 펼쳐지는 것을 보고 매우 즐거워할 것 입니다. 아마도 어느 날 은손의 기저에서 무장한 다음 위대한 수비자 빛을 보거나 알론스 대성당에 성직하는 것을 볼 것입니다. 그 결과와 상관없이, 우리 일은 언젠가 큰 열매를 맺게 될 것입니다."
rows["342:1139540968"]="무한 용 비행은 아타스 메네틸 왕자의 운명을 바꾸려고 합니다.$B$B이제 당신은 그를 리치 왕하지만 여기와 지금 그는 여전히 로데론 그의 왕국을 위해 가장 좋은 일을 하려고 노력했습니다.$B$B아타스는 오늘 매우 운명적인 선택을 하고 있습니다. 그리고 우리는 시간경호가 말하는 시간선의 전환점이 될 것입니다."
rows["342:718338828"]="\"아침\"을 받는 사람 은 '아침'을 받는 사람 이 될 수 있습니다.$B$B또한 숙소 소유자와 이야기하여 화석을 얻을 수 있으며, 나중에 화석을 사용하여 그 숙소로 빠르게 돌아갈 수 있습니다."
rows["342:802183307"]="시로나스의 생각이었어, 이 혐오는 그들 자신의 것입니다. 그는 드레네이 군계 중 고위급의 일원입니다.$B$B그 물건은 거대하고 강력하고 분노가 가득한 거요."
rows["342:828447850"]="첫 번째는 가장 강력한 하카리 중위인 진도와 혈통주로부터 가져야 할 원시적 상징입니다.$B$B두번째는  ⁇ 두 인형입니다. 이 쓰레기 덩어리 안에 있습니다. 이 불쾌한 곳을 담아내고 있습니다.$B$B이 것들을 가져오면, 나는 당신에게 강력한 매력을 만들거야!"
rows["343:1205954152"]="안녕하세요, 아르헨티나 콜로세움에 대한 발키르 전투를 치고 싶으세요? \010본 회담은 현재 선택된 공격 어려움에 해당하는 버전입니다. 이 회담은 진행 중입니다. 블리자드 포럼에서 발생하는 모든 버그를 보고하십시오.\010만남을 시작할 준비가 되셨습니까?"
rows["343:1509702714"]="<잡힌 선하크 요원이 웃는다>$B$B걱정 마 신혈, 포털 컨트롤러도 많고 포털에 더 적합한 장소도 많고 시로나스가 곧 새로운 게이트를 갖게 될 것이라고 확신합니다. 이 푸른 피부의 개들은 이 세상에 오래 가지 않을 것입니다. 시로나스와 혐오스러운 것은 선하크 세력이 남긴 모든 것을 청소 할 것입니다."
rows["343:205895247"]="알도르가 벽을 짓는 걸 지켜봤는데 도시 전체를 재건할 거야$B$B레이크샤이어년] 고령 포먼 오슬로보다 훨씬 더 빨리 작동합니다. 그는 호수에서 도구를 잃지 않고, 아니면 기둥들이 그의 물품을 빼앗아갈 것입니다.$B$B알도르에게 도움을 청하면 다리가 더 빨리 수리될 수 있어"
rows["343:292463101"]="우두마의 82-84 수준의 던전인  ⁇ 텍스 피널은 이제 초기 테스트에 사용할 수 있습니다. 던전은 진행 중입니다. 던전에 이동하기 전에 전체 그룹에 들어와 주시기 바랍니다.\010도각지대에서 나가려면 헤어스톤이나 비슷한 방법으로 탈환해야 죽고 방출되면 이 NPC에서 다시 탈환해야 합니다"
rows["344:108016146"]="친구 - 스톰윈드 당신의 도움과 너그러운 도움이 필요합니다!$B$B한때 큰 섬유 물품 저장소 가 비약적 으로 부족 해졌다. 스톰윈드 는 이제 섬유물 및 붕대 제조 를 위해 그 물품 저장소를 재건 하기 위한 다방면적 노력 에 참여 하고 있다. 당신 의 섬유물 기증 은 스톰윈드 의 인적 을 극히 도울 것 이며, 시민들의 존경 을 받을 것 이다!"
rows["344:1132956675"]="<예스라의 꿈 같은 비전은 눈앞에 떠다니고 있는데, 그녀의 관심은 갈라지고 있습니다.$B$B수년 동안 아비아나는 내 꿈의 가장자리에 떠돌았는데, 그녀가 우리에게 돌아올 수 있을지 궁금했습니다.$B$B하지만 우리가 이 산을 구하기를 희망한다면 더 즉각적인 우려가 있습니다."
rows["344:1211582887"]="재미있는 사실은 모구지아라는 뜻입니다. '모구의 집'이라고 번역합니다. 하지만, 속이는게 아니죠. 이것은 그들의 유일한 집이 아닙니다. 그것은 사람들이 이 곳을 붙인 이름일 뿐입니다. 저는 약간의 연구를 했고 이 지역의 원래 이름은 쇼크가프라는 것을 발견했습니다. 그건 이상하다. 단지 우연한 기회일 것입니다."
rows["344:1264596405"]="<고이아 할머니는 허약하게 웃는다.>$B$B물론 안 돼, 사랑하지만...$B$B가로쉬가 마하르를 이끌 수 있어 그는 강하고 지혜로운 모든 영들이 그를 승인하고 자기 자신을 믿어야만 한다 그는 너무 두려워하고 너무 깊이 두려워하고"
rows["344:1477894292"]="윈드런러 여인이 직접 나를 호드 새 워시프 가로쉬와 함께 찢어진 울타리를 고쳐보고 있는 것 같습니다.$B$B어쨌든 Twilight 위협을 한 번이나 끝내야 하지만 가장 중요한 것은 최강의 무기를 만들지 못하게 해야 한다는 겁니다"
rows["344:1576188596"]="안녕하세요, 친구들, 그리고 아제로스에서 가장 위대한 쇼에 오신 것을 환영합니다!$B$B여러분, 우리 가 제공하는 모든 것 을 맛보시기 바랍니다. 그 들 의 경치를 보시기 위해 오셔서 놀아보세요. 이 광대하고 신비 한 세상 에서 암흑 달 요정 이 발견 한 놀라운 일 들 에 놀라십시오. 우리는 모든 연령대의 어린이 들 이 즐길 수 있는 흥미 를 가져오기 위해 어떤 비용도 절약 하지 않았습니다."
rows["344:1590238389"]="도움이 필요해요 제 몸을 찾고 있어요 이 동굴 어딘가에 있지만, 영계만 있으면 볼 수 있습니다.\010하지만 경고해 시간 없는 영들이 우리를 영세계에서 쫓아낼 수 있고, 만약 그렇게 한다면"
rows["344:380273283"]="성공! 난 지옥불 성과 그 안에 있는 마법에 맞춰서$B$B그 곳에는 수많은 악성코드가 있지만, 그것만이 아닙니다.$B$B만약 당신이 자신을 열면, 나는 당신의 마음을 잡을 것입니다. 잠시만, 당신의 마음을... 그리고 페르진으로 펜을 가져와"
rows["344:572832149"]="내가 말해야 할 것도 없지만 배드랜드의 모든 짐승과 짐승을 넘어서면 시어링 골짜기에 도착할 수도 있습니다.$B$B카가스 근처에 오크들이 만든 뒷길이 있는데, 우리가 어떤 멍청이를 대하는지 보여줘요."
rows["344:581958211"]="난 카드거, 전 추락한 자들의 연습생 수호자메디프, 당신은 그 이름을 들어본 적이 있을 겁니다.$B$B메디브가 악인 사르게라스가 점령한 것을 발견한 사람이 나였는데, 그는 이 세상과 아제로스 사이에 어두운 포털을 열었다."
rows["344:709448891"]="튀어 라지파우라는 거북이$B$B이 사람은 남쪽 땅 출신이고, 템버마우 부족 출신이었습니다.$B$B그는 우르소크를 보고 싶어했고 보드라시일의 흠이 깨끗해져 아버지를 구해 줄 수 있다고 생각했지$B$B그런 희망은 어리석은 일이고, 당신이 그것을 인정할 때 어둠이 그를 괴롭혔을 때,"
rows["344:829337757"]="잠깐, 어디로 가는데? 이송이 필요했지? 그냥 끝낼까요?$B$B난 루를 보내야 한다 어둠의 분자를 직접 배달해 줄게$B$B맞아요, 루...\010"
rows["345:1363571504"]="내가 마지막으로 홀에 갔을 때 타롱 왕 이키스는 테록의 퀸을 가지고 있었고 그의 권위를 나타내는 증거였습니다.$B$B내 동생인 다크웨이버 사이스는 우리의 의식에 테록 마스크를 착용했습니다.$B$B테록의 사거에 대해서는 정확히 어디에 있는지 알 수 있는 방법이 없지만, 그들은 보통 큰 돔 홀에 있는 룬 주위의 중심에 보관했습니다."
rows["345:1633384867"]="여러분들은 모두 서두르고 또 다른 위험한 괴물들을 죽일 수 있을 겁니다. 하지만 잠시만 기다려서 이 구석에서 나와서 도와줘요."
rows["345:1741854875"]="<고위검사 페어뱅크스는 머리를 흔들고>$B$B아니... 그는 뒤에서 서, 죽은 무사들의 군대가 우리 위에 내려오는 것을 지켜보고 있었습니다. 얼마 지나지 않아, 제 힘이 마쳤어요. 나는 먼저 쓰러졌어요. "
rows["345:1820925200"]="아나키라지에서 시리투스 사막에 큰 문제가 있습니다. 얼라이언스 이 번엔 곤충들을 막기 위해 모든 노력을 기울이고, 그래서 여기 있는 모든 사람들을 보고 있어요.$B$B이 호드 내가 모을 수 있는 건 $2009w 전쟁에 대한 노력, 하지만 나는 단지 $2008w그럼 도와줄게?"
rows["345:2036018795"]="이더리얼에 대해 뭘 알죠?$B$B의심할 여지 없이 여러분은 우리 모두를 같은 관점에서 보고, 서로 다른 분파들 사이의 갈등과 투쟁을 무시합니다.$B$B아마 소개가 올 때가 됐을 겁니다. 저는 보호국의 아미어 지휘관입니다. 또한 이 지역에서 빈 생물과 이더리움의 침해를 해결하는 유일한 희망입니다.\010"
rows["345:432433125"]="아누바라크 전투를 벌이고 아르헨티나 콜로세움에 대한 공격을 해보고 싶으세요? \010본 회담은 현재 선택된 공격 어려움에 해당하는 버전입니다. 이 회담은 진행 중입니다. 블리자드 포럼에서 발생하는 모든 버그를 보고하십시오.\010만남을 시작할 준비가 되셨습니까?"
rows["345:678781048"]="나는 소리치기를 원했지만, 입술에서 작은 숨결이 빠져나왔다. 이 반란 행위로 인해 즉시 때려졌다. 나는 땅에 누워있을 때 마티스가 사라우안의 몸 앞에 걸어가고 있음을 볼 수 있었다. 그는 눈에 띄게 걱정되었다. 그는 시로나스 또는 시로나 또는 그러한 어떤 존재가 그의 뼈에서 그의 고기를 찢어질 것이라고 말했다. \010"
rows["346:1435884279"]="\"타우라헤?\"$B$B타우렌 드루이드는 기대감 으로 당신을 바라보고 있지만, 당신은 그녀 와 말 그대로 소통 할 수 없다는 것 은 분명 하다. 그녀는 두려움 없이 자신 을 가리키고 미소 합니다. 그녀는 당신 을 가리키고 또 다시 미소 합니다. 마침내 그녀는 남쪽으로 가는 길 아래로 여러 번 움직입니다.$B$B어쩌면 그녀는 당신이 더 나아가서 이야기 할 수있는 드루이드가 있다는 것을 나타냅니다?\010"
rows["346:1923864930"]="그게 충분하지 않았습니다.$B$B<페어뱅크스  ⁇ 은 웃음, 기억에 빠진 것>$B$B수천 명이 왔고 천명이 죽었습니다. 빛! 모그라인의 힘으로! 그는 그들이 올 수 있는 빨리 그들을 때리겠다고 했습니다. 혼란을 통해, 나는 작은 모그라인이 여전히 멀리 떨어져 있다는 것을 깨달았습니다. 나는 그에게 \"우리에게 도움을 주십시오, 르노! 당신의 아버지를 도와주세요, 소년!\"라고 부르게 되었습니다."
rows["346:431259119"]="드래곤의 입은 얼라이언스에 그들의 첫 번째 실제 발걸음을 줄 수 있도록 설립되었다. 스톰윈드와  ⁇  모로흐 사이에 위치하고 있음에도 불구하고, Badlands는 전통적으로 호드 영토였다.$b$b만약 그 변화가 일어나면, 우리는 스스로를 주장하기 시작해야 합니다. 물론, 뉴 카가스에 대한 용의 공격은 우리의 사유에도 해를 끼치지 않습니다."
rows["346:465033036"]="이건 심각한 질문인가요?$B$B만약 여러분이 너무 더러워지기를 두려워하는 겁쟁이라면, 불타는 스텝과 세어링 골목의 생물들 위에 어두운 철의 잔해가 있을 겁니다.$B$B만약 당신이 혈통에 갈망하는 모험가라면 블랙록 스파이어와 검은바위 나락의 동굴에는 잔재가 꽤 많이 있습니다."
rows["346:528712614"]="난 그 호드 자신의 군대를 모아서 노스렌드- 네 얼라이언스 그리고 호드 그들은 공격력을 실제 위협에 집중시킬 수 있습니다.$B$B어떻게든 제 경험에서 이런 일이 일어날 가능성이 낮다고 생각합니다.$B$B<발레라는 자기 자신에게 분노하게 고소한다.>"
rows["347:1095871069"]="고마워 영웅, 당신과 당신의 동료들은 얼라이언스 판다리아를 탐험하고, 밸리를 확보하고, 결국 가로쉬의 요새를 공격하는 것이 이 승리를 가능하게 한 것입니다.$b$b우리의 이기는 칼림도어에서 전투를 막을 수 있지만 평화에도 불구하고, 여기서, 고향에서 그리고 다른 곳에서 할 일이 많이 있습니다."
rows["347:1223662260"]="투슈이의 길은 올바른 관점을 얻는 것입니다. 명상과 고려를 통해 우리는 모든 문제에 가장 효과적인 해결책을 찾습니다. 연습과 징계로 우리는 우리의 의지의 완벽한 도구가 될 수 있도록 우리 몸을 고르게합니다.$B$B투슈이족의 길을 따라 사는 것은 온화한 정신과 무방한 형태를 모두 존중해야 합니다."
rows["347:1540628376"]="먼저, 한 개의 다크월 게임 토큰을 대가로 펠렛 총을 줄게요$B$B그 다음엔 발광하는 표적을 쏴요$b$b발광 직후 목표물을 타는 데 충분히 빠르면 승점도 더해집니다.$b$b만약 당신이 그 시간까지 점수 한계를 달성하지 못하거나, 상자에서 벗어나면 걱정하지 마세요. 점수는 다음 경기에 전달됩니다."
rows["347:1562529600"]="지식 은 힘 이다. 나의 젊은 친구, 진정한 힘 이다. 당신 은 그 힘 을 최대한 많이 습득 하고, 이미 그렇게 해 온 사람 들 을 적절 히 고려 하는 것 은 현명 할 것 이다.$B$B태양강을 파괴하기 전에 우리는 우리 문명의 꼭대기에 가까워졌다고 생각하면서 스스로를 속였죠. 스컬지 우리를 무릎을 꿇게 하고, 어떤 의미에서 현실로 되돌려 놓는 것입니다."
rows["347:182661443"]="어둠의 포털이 열리면서 내 백성의 운명에 대한 소식이 전해졌습니다. 제 망명으로 인해 그들의 멸망에 참여하지 못했지만,$B$B전 제 형제들이 그런 일을 할 수 있다고 상상도 못했어요$B$B내가 꿈꾸던 고향은 절대 일어나지 않을 거야 이 숲이 내가 남은 유일한 집이야"
rows["347:2124417995"]="숙소는 모험을 마치고 휴식을 취할 수 있는 곳입니다. 만약 이런 숙소에서 안 머무르면, 다시 사막으로 돌아간다면 완전히 휴식하지 못할 것입니다.$B$B또한 어떤 숙소에서도 화석을 구입할 수 있고, 나중에 휴식을 취할 준비가 되면 이 화석을 사용하여 당신이 그것을 얻은 숙소에 다시 데려갈 수 있습니다."
rows["347:212569020"]="비극적으로, 트롤의 지혜가 마침내 악마의 주인과 그의 하위인 사이의 유대감을 봉인했다. 악마의 주, 그림자  ⁇  세파와 오그를 결합시키는 촉매 역할을 했던 트레보르의 군대는였다. 거의 무제한의 힘의 유혹과 각각의 지도자에게 불멸의 충격 군대를 부여하는 것은 거래를 피로 봉인했다.\010"
rows["347:611382472"]="이리던 의 놀라움 으로, 그는 훈련 의 일부분 인 고통 스러운 통과 의식 을 성공 한 것 뿐 아니라, 이미 많은 참전 의 악마 사냥꾼 들 보다 더 뛰어난 능력을 발휘 하고 있었다.$B$B이리리던은 바디스에게 잠재력을 느꼈고 세 명의 악마 사냥꾼을 임명하여 그들의 방식으로 더 훈련하도록 했습니다."
rows["348:1089727451"]="제이나는 즉시 당신을 따뜻하게 해줍니다.$b$b친족한 영혼이군요 $p내 투쟁을 이해해 보군 매일 힘든 결정, 밤마다 악몽$b$b하지만 키린 토를 지키기 위한 책임은 내 몫이고, 이 일에 함께해줘서 기쁘다. 왕은 이런 식으로 보지 않을거야."
rows["348:444850613"]="<제이나의 눈은 슬프게 변한다.>$b$b그래서... 당신은 도시를 순결시키고, 태양수들을 집 밖으로 쫓아낼 것인가?$b$b우리 둘은 분명히 매우 다르지만, 제 역할과 키린 토르의 임무는 조금 다르게 생각됩니다."
rows["348:739450163"]="내가 아는 대로 모든 것이 모이고 마지막 재물이 조립되고 센리온 홀드에 보내지고 있습니다. 마지막은 하루도 안 되는 시간 안에 도착해야 합니다. 우리의 장비와 군대가 모두 거기에있을 때, 이동 모래의 왕봉을 들고 있는 사람은 Ah'Qiraj 근처에  ⁇ 을 울릴 수 있습니다. 문들을 열기 위해."
rows["348:757803252"]="난 이 말도 안 되는 것에 시간을 갖고 있지 오글로스포프랑 한 번만 기회를 잡았어$B$B타나리스로 가서 나라인 사우스판시의 동굴을 찾아내야 할거야 그 동굴에는 마법 같은 책이 있어$B$B이제 길을 잃어!"
rows["349:1533364582"]="아르젠트 콜로세움에 대한 전투에서 호사르크스 경주와 싸우길 원하십니까? \010본 회담은 현재 선택된 공격 어려움에 해당하는 버전입니다. 이 회담은 진행 중입니다. 블리자드 포럼에서 발생하는 모든 버그를 보고하십시오.\010만남을 시작할 준비가 되셨습니까?"
rows["349:1643672999"]="그녀는 아름다운 여자야? 스카이'리... 우리 지휘관의 충실한 기리폰. 쿠르드란은 자신, 그는 그의 관객을 요새에 보유하고 있습니다. 나는 그가 바쁜 때 우리의 스카이'리를 위해 여기 신경쓰고 있습니다. 멋진 생물, 그녀는, 그들이 오는만큼 강하고 격렬합니다. 그녀는 쿠르드란에서 죽을 것입니다. 당신은 전에 본 적이 없는 더 충성스러운 영혼.\010그녀를 돌보는 게 영광입니다"
rows["349:1732257076"]="카엘타스에게 복수를 치겠습니다. 키린 토르에 대한 분노를 위해요.$B$B심판이 있을 것이라$B$B<아크마지스는 시원하게 진부하며, 전망에 만족하지 않는다.>$B$B카엘타스는 단순한 악당 마법사일 뿐 아니라 내가 탑에서 해방되면, 라반드루와 나는 그를 반대하는 모든 사람을 도울 것이다."
rows["349:1897652667"]="이건 끔찍해요! 내가 여기 앉아있어야 할 일이 너무 많고, 쓸모없어야 하지요! 만약 내 팔이 노스렌드에 다치지 않았더라면... 그 문제에 대해 계속 고민하는 것은 쓸모없습니다!\010전선에 있지 않아서도 어떻게든 도움을 줄 수 없어"
rows["349:340322351"]="히알 산의 계곡과 정상, 실리투스 산의 변하는 모래를 건너, 레지옹의 무서운 군대에 맞서 싸웠어요. 우리는 이름 없는 얼굴 없는, 얼라이언스의 아들들과 딸들입니다. 빛와 얼라이언스의 힘으로, 첫 번째 공격은 우리에게 속하고 마지막 공격은 우리의 적들이 보는 모든 것입니다.$B$B우리는 7 레지옹입니다.\010"
rows["349:546113389"]="어리석은 필사자 - (Usurper의 자녀들!) 당신은 아무것도 하지 않았다 - (저신들의 새끼!) 나는 여기서 말하고자 한다. (말, 말, 단어. 마스터가 살인을 원한다.) 모든 것이 혼란에 빠진다. 모든 것은 파괴될 것이다. (Chaos, chaos!) 오늘 여기 있는 당신의 일은 아무 것도 바꾸지 않는다. (Chaos , chaos, 모든 것이 끝납니다) 어떤 필사자가 당신이 가지고있는 것을 보고 살 수 없습니다. 당신의 끝이 왔습니다."
rows["349:632996263"]="\"다르나사에?\"$B$B밤 elf druid 는 기대 를 가지고 당신을 바라보고 있지만, 당신은 그녀 와 말 그대로 소통 할 수 없다는 것은 분명합니다. 그녀는 두려움 없이 자신을 가리키고 미소 합니다. 그녀는 당신을 가리키고 다시 미소 합니다. 그녀는 마침내 북쪽으로 몇 번 이동합니다.$B$B어쩌면 그녀가 더 멀리 갈 수 있는 드루이드가 있다고 지목하고 있을지도 몰라?"
