rows["350:1131793880"]="그녀는 즉시 하비 레갈로 돌아가라고 요구했습니다! 브랜은 그런 거저가 없으니까요. 그는 군대가 우리를 지원하지 않으면 그 하비에 돌아갈 수 없다고 말했습니다. 그것은 너무 위험했습니다. 우리가 처음 그들을 모험했을 때 그 냄새가 나는 곤충의 수가 세 배로 증가한 것 같았다.$B$B나탈리아가 정신을 잃었을 때야!"
rows["350:1147737201"]="순례자의 보물을 최적화하는 데 필요한 물적 요소는 매우 놀랍습니다. 수많은 원료, 많은 노동, 수천 개의 상자, 수천 개의 완성품이 여기 저기 그리고 모든 곳에서$B$B솔직히, 저는 꽤 인상적이어서 배고프네요... 난  ⁇ 두파이의 냄새를 맡을 수 있어요."
rows["350:121937137"]="저는 아버지를 섬기고 그의 계획을 존중하지만 제 자신의 정의에 대해서도 섬세합니다. 저는 블랙록 형제들의 배신을 충분히 봤습니다. 수천 권의 책을 채울 수 있습니다. 그리고 이제 그들은 맹목적인 영토주의를 제외하고는 레드리지에 침입할 계획을 세우고 있습니다.$b$b배신은 여기서 끝납니다. 마지막 장이 올 때가 됐습니다. 그리고 행복한 끝은 없을 겁니다."
rows["350:189094390"]="총, 다이노amit, 폭탄, 폭발하는 양... 사랑하지 않는 것은 무엇입니까? 무역의 머리의 이러한 그리고 다른 많은 흥미로운 도구를 만드는 방법을 배우기 위해 언더시티, 브릴 남쪽의 로데론의 유적 아래. 유적의 뒷부분에서 엘리베이터를 가져. 도착하면 언더시티 보호자 중 한 명에게 트레이너가 정확히 어디에 있는지에 대해 이야기하십시오."
rows["350:639639264"]="역사, 문화?  ⁇ . 그런지 학자와 기록자의 영역입니다.$B$B우린 리리쿼리에 있는 사람들이 바로 지금과 어쩌면 미래에 대해 걱정하고 있습니다.$B$B우리는 잃어버린 유물, 부와 전통을 발견하고 수집하여 우리에 대항할 수 없도록 합니다. 결국 권력은 가장 잘 사용하는 사람들의 손에 속합니다."
rows["350:664027588"]="제 아버지가 옳은 일을 한 것 같아요 오그리마그리고 나머지 사람들은 호드우리는 이미 그 길을 걸었고, 효과가 없습니다.$b$b전쟁 유도자 한 명을 퇴진시키고 우리가 함께 일할 수 있는 지도자로 교체했습니다."
rows["351:1308968881"]="그건 힘이야, 멍청이$B$B<Mataus의 눈은 어두워진다.>$B$B이 멍청한 사람들은 당신 같은 멍청한 사람들을 낙스라마스로 보내서 비정신한 갑옷을 가져오게 하고$B$B<Mataus 스프링>$B$B그런 바보같은 생각만 하면 목에  ⁇ 이  ⁇ 니다.$B$B나도 그 무기를 찾고 있지만, 가장 더러운 형태에서"
rows["351:1446049961"]="영원한 꽃의 계곡에서 끔찍한 일이 일어났지만 진짜 비극은 낚시하기에 더 이상 좋은 곳이 아니라는 것입니다.  $b $b다행히도 동부 해안에서 여전히 보석 다니오를 낚시할 수 있는 섬을 들었어요. 소문이 사실이라면,"
rows["351:1607016854"]="메슬리 부인에게 오신 것을 환영합니다.$b$b만약 당신이 배를 묻는다면, 자유롭게 물어보세요. 그렇지 않으면, 제가 항상 하는 것처럼 여행을 즐기세요. 결국, 제가 좋아하는 작가의 말을 인용하자면:"
rows["351:563923012"]="안녕하세요, 당신은 노스렌드 아르헨티나 콜로세움에 대한 괴물 만남? \010본 회담은 현재 선택된 공격 어려움에 해당하는 버전입니다. 이 회담은 진행 중입니다. 블리자드 포럼에서 발생하는 모든 버그를 보고하십시오.\010만남을 시작할 준비가 되셨습니까?"
rows["352:1777819357"]="네, 그랬습니다. 작은 모그라인의 충격을 받아 스카르렛 수도원으로 돌아갔어요. 외쳤고 소리쳤습니다. 이야기를 듣기 원하는 모든 사람들에게 전했습니다. 그리고 제 행위로 인해 냉혈로 살해당하고 이 방으로 끌려가게 되었습니다."
rows["352:273156698"]="브루페스트에서 더 많은 배가 필요해$b$b내 개인적인 양떼 중 한 마리에게 줄임수를 빌려줄게$b$b매번  ⁇ 을 가져오면, 몇 개의 토큰을 줄게 되는데,  ⁇ 을 더 오래 사용하게 해 줄게 되죠.  \010일단 시작하면 내일까지 다시 할 수 없을 거야\010이 일을 할 준비가 됐는지 확신하십니까?"
rows["352:725833873"]="내 뒤에, 처음 들어온 곳에는 열풍기가 있는데, 온기가 올라와 나오는 곳이죠.$b$b또 한가지 말씀 드리겠습니다. 동료 드루이드들에게 전해지는 보고서에 따르면,"
rows["353:428560527"]="내가 시티파이라는 말을 들었어?$B$B물론 난 다운스 블로소스에서 자랐지만, 할아버지를 몇 번 방문했었는데, 카라토와 톱니의 차이를 알고 있어요.$B$B할아버지가 돌아가신 후 농장을 내게 맡겼어요 그래서 최선을 다하겠다"
rows["353:933872544"]="죄송하지만, 저는 스톰윈드의 왕국에 적어도 높이 평가받지 않은 개인에게 말을 팔지 않겠습니다. 이 말들은 어디서나 찾을 수 있는 가장 훌륭한 말들입니다. 그리고 우리는 확실히 그들을 우리의 적들의 손에 넣고 싶지 않습니다.$B$B네, 네, 네. 네, 네. 스톰윈드 그리고 나서 사업을 할 수 있습니다."
rows["353:986835016"]="아르헨트 콜로세움에 대한 공격에 대해 팩션 챔피언스 대결을 하고 싶으세요? \010본 회담은 현재 선택된 공격 어려움에 해당하는 버전입니다. 이 회담은 진행 중입니다. 블리자드 포럼에서 발생하는 모든 버그를 보고하십시오.\010만남을 시작할 준비가 되셨습니까?"
rows["354:1004473658"]="이 책은 그들의 세계를 파괴한 재앙에서 살아남았는데 그 자랑스럽고 어리석은 사람들은$B$B코데크스 소유자 인 당신 이도 그렇게 할 수 있습니까?$B$B당신은 모머를 불러올 수 있는 무방방법을 고안했나요? 아니면 이 불성스러운 페이지에서 조심스럽게 속삭이는 다른 존재들 중 하나라도요?$B$B- 그럼 보자"
rows["354:1248800002"]="왜 계속 죽었다고 말하는 거야? 누가 죽었다고 말했어?$B$B그냥 사라졌어$B$B보시다시피 우리는 마치 큰 오크와 어두운 철의 왜성과의 전투 중이었는데, 오크들은 그들이 어긋나고 비참한 저주자였는데,"
rows["354:1274749108"]="죄송하지만, 저는 스톰윈드의 왕국에 적어도 친근한 사람이 아니라고 여겨지는 개인에게 말을 팔지 않겠습니다. 이 말들은 어디서나 찾을 수 있는 가장 훌륭한 말이고, 우리는 확실히 그들을 적들의 손에 넣고 싶지 않습니다.$B$B네, 네, 네. 네, 네. 스톰윈드 그리고 나서 사업을 할 수 있습니다."
rows["354:1302300638"]="스톰윈드 의 라이더 들 은 두려움 이 없고 파괴적 인 혐의 를 자랑 한다. 그 들 의 기술 과 잔인 함 은 자신 에게 충고 을 받더라도 바로 다시 충고 하는 것 이다.$B$B가까이서 서고 밀어주려고 해봐, 그리고 그들이 거리를 뻗어 나가기 전에 스킬드 브레이커를 가지고 균형을 잃게 해줘요. 그렇지 않으면 그들은 항상 당신을 마주하게 될 겁니다."
rows["354:1343525774"]="오그리마 의 라이더 들 은 두려움 이 없고 파괴적 인 혐의 를 자랑 한다. 그 들 의 기술 과 잔인 함 은 자신 에게 충고 을 받더라도 바로 다시 충고 하는 것 이다.$B$B가까이서 서고 밀어주려고 해봐, 그리고 그들이 거리를 뻗어 나가기 전에 스킬드 브레이커를 가지고 균형을 잃게 해줘요. 그렇지 않으면 그들은 항상 당신을 마주하게 될 겁니다."
rows["354:1714894848"]="탈북에 대한 치열한 보복이 이어질 예정이었으며, 샤트라스 시는 일리던과 칼타스의 끊임없는 공격에 직면했다.$B$B나가와 브로oken의 군대가 도시 안으로 쏟아져 들어갔지만, 사타르의 힘으로 격퇴당했습니다.$B$B나아루족은 한 가지 명확하게 깨달았는데, 그들이 레지옹을 쫓으려면 먼저 이리lidan을 물리쳐야 한다는 것입니다."
rows["354:1812404765"]="드레나이 개, 네가 사루안이라고 부르는 사람이 내가 그를 때릴 때 아기처럼 울었다는 것을 알고 있었는가? 나는 높은 계급의 한 사람을 손에 쥐고 있다는 것을 알고 유포리아의 감정이 날려갔어요. 시로나스의 계획이 아니었다면, 내가 그를 죽게 고문했을 것입니다.\010"
rows["354:322921359"]="우리 중 일부는 사제, 마녀가기도 했지$B$B'젠타브라의 얼굴은 남쪽으로 향하는 시선으로 굳어진다.'$B$B우리는 영들이 우리와 화를 내리고 있다고 생각했지만, 젤라잔이 우리를 천천히 앗아가는 것 같지는 않았죠. 우리는 그가 강하지만, 그 강하지는 않았다는 것을 알고 있었습니다. "
rows["354:327341976"]="내가 알고 있는 대로 모든 것이 모이고, 마지막 재질이 조립되고, 센라리온 홀드에 보내지고 있다. 마지막은 $2113w일 이내에 도착해야 한다. 우리의 장비와 군대가 모두 도착하면, 이동 모래의 왕좌를 가진 사람은 아안키라지 근처에  ⁇ 을 울릴 수 있다. 그 다음, 전쟁이 시작될 것이다."
rows["354:471548820"]="우매한 존재가 우리를 도전해 내려고 하는 그의  ⁇ 은 시체는 이리던 스톰라이지의 힘을 레지옹에게 상기시켜 줄 것입니다.\010$b그림자 클록의 마법은 더 이상 우리를 숨기지 않고 사라지고 있습니다. 그것은 오래 동안 재미있었습니다. 하지만 나는 적에게 죽음을 가져오는 보다 직접적인 접근 방식을 선호합니다.\010$b잘 싸웠지만 나 가는 곳으로 혼자 가야 돼"
rows["354:91929976"]="영웅이 좋아서 배틀랜드를 거쳐 세어링 골짜기를 찾아서 영웅성을 증명하는 걸 가져오면$B$B시어링 골지의 동남쪽 가장 먼 곳에 나와 거의 같은 강인 여인이 있는데,"
rows["354:989526629"]="워치프는 모든 종류의 무기와 장갑을 연구하도록 지시했습니다. 그는 불모의 땅에서 타우렌과 오크 문화의 중심지로 보내서 가능한 많은 여행자들을 만나고 불모의 땅 문화에 대해 알아내도록 했습니다.$B$B그는 가장 아픔스러운 문화에서 배울 것이 있다고 생각합니다."
rows["355:1563195927"]="네, 보네스카이트, 우리 테너인 돈 줄리오라는  ⁇ 이랑이 이 모든 일을 시작하게 해줬어 로데론도누리오는 많은 흥미로운 기술을 습득했습니다. 그 중 하나는 쓰러진 사람들의 뼈를 스컬지 그리고 치명적인 가죽 장갑으로 만들죠. 살인범에게 적합합니다."
rows["355:207467229"]="제이나는 미소를 짓는다.$b$b네 힘과 신념을 공유하고 있다면!$b$b하지만 네 말이 맞아요 키린 토르는 나보다 더 크죠 얼라이언스 또는 호드저는 그것을 지키고, 그리고 그 힘을 현명하게 사용해야 합니다.$b$b당신과 나는 동의하는 것 같지만 왕이 그렇게 생각하는 건 의심스럽지만 안두인을 설득할 수 있다고 생각하십니까?"
rows["355:2113749073"]="대부분의 얼라이언스군은 아제로스으로 떠났고, Turalyon 장군과 함께 보내진 신중하게 작성된 보고서가 다라란으로 안전하게 돌아갈 수 있기를 바랍니다.\010네르즈울의 무분별한 포털들은 파라홀론을 찢어 버렸고, 그 녹색 언덕은 이제 뒤틀린 황천가 지구를 부패시키면서 빠르게 붕괴되고 있습니다.\010"
rows["356:1572975758"]="이 과제 중 하나를 맡으면 양을 빌려줄 겁니다. 이것은 대출입니다. 그래서 영원히 지속되지 않을 것입니다. 양은 느려 보일 수도 있지만, 조금은 제압을 완화시켜서 그는 속도를 올릴 것입니다.$b$b양떼는 사과 좋아해요. 우리는 몇 개씩 사과를 넣었거든요. 그래서 꼭 지나가세요. 사과 먹는다면 양떼는 얼마나 피곤했는지 잊게 될 겁니다."
rows["357:1475651601"]="네, 그게 그녀의 이름이고, 그녀는 훌륭한 배입니다.$b$b이런 배에서 배울 것이 많아요. 위대한 시인이 한 번 말했죠. 밤이 지나고 지나면서 서로 말하는 배들은 단지 신호만 보여지고 어둠 속에서 멀리 있는 목소리만 들려요. 그래서 생명의 바다에서 우리는 지나고 서로 이야기합니다."
rows["357:1682272112"]="솔직히, 이 사람들이 어떻게 계속 잡혀있죠?$B$B괴물인 것만으로도 부끄러워요$B$B부끄러움에 대해 이야기하자면, 내 게으른 비서님은 어디 있어요?$B$B천재로 인한 부담은, 우리 모두 이 혼란에서 나 혼자 빠져나갈 수 있을 것 같아요."
rows["357:17517139"]="하지만 식물학에 대한 실력을 가지고 있다면 더 많은 보상을 얻을 것입니다. 특별한 씨앗을 키우고 재배해야 합니다. 눈먼 채로斧을 흔들거나 그림자를 지나가면서 야만적으로 gesticulating 하지 말아요. 여러분이 받을 Evergreen Pouch는 가장 간단한 무작위도 어떤 것을 키울 수 있도록 해주지만, 어떤 능력을 보이는 사람은 더 풍부한 결과를 얻을 것입니다."
rows["357:2038300498"]="레슬러가 내 구 연습생을 죽였어 이제 넌 제 연습생이 될 거야 운의 냄새와 땀의 향기가 있어$b$b레슬러는 느려지만 강해$b$b또한, 그의 정신은 약해져 있습니다.$b$b약해지면 내 옆에 있는 바구니를 이용해 신선한 식품을 먹어$b$b행운을 빌어, 거머리 연습생!"
rows["357:504045360"]="자, 제가 소개해 드리겠습니다. 저는 예 फाय러보입니다. 이 옛 마법의 마을의 명예로운 지도자입니다.$B$B분명히 당신은 정직한 세계 시민입니다.$B$B이 어려운 상황을 풀어주시겠어요? 가까운 피난처의 샤도파인은 불편한 것에 보상을 기꺼이 해주실 겁니다."
rows["357:859034259"]="내가 뭘 하고 있는 것 같아? 내가 직접 꾸려서 살 수 있도록$B$B숲에서 운영되는 기지가 있어 샤트라트, 알레리안, 스톤브레이커, 그리고 센리온 드루이드가 뭘 하고 있는지 알아내는 것이 더 쉬워요$B$B잠깐, 내가 당신을 알고 있나요?"
rows["358:1002455865"]="보석 을 찾는 데 있어서 가장 중요한 방법 은 보석 을 찾기 위한 5개의 석류 덩어리 에 있는 보석 을 채취 하기 위해, 단순히 보석 을 찾는 능력 (마술 책 의 직업 탭 에서 발견 할 수 있 는 것) 을 사용 합니다.    \010더 좋은 품질의 광석은 더 귀중한 보석을 제공하므로 구리 광석보다 더 높은 품질의 보석을 발견할 수 있습니다."
rows["358:1004975521"]="이 곰은 미스터럴 호수와 얼라이언스 은바람 피난처의 전지대. 잿빛 골짜기 헌트, 그는 장난을 치면 안 됩니다. 그의 존재는 잿빛 골짜기 그리고 스톤탈론 산맥"
rows["358:1521392289"]="난 가로쉬의 욕망을 이해해요. 모든 오크들 사이에서 전투에 대한 갈망이 강합니다. 특히 우리 사람들을 죽인 적에 대해요. 하지만, 전쟁 지도자는 전략은 전투에서 힘만큼이나 중요하다는 것을 반복해서 증명했습니다.$B$B우리는 이제 더 이상 정신이 없는 악마가 조작한 야만족의 집단이 아닙니다. 호드."
rows["358:1539687713"]="난 변명하지 않네, 거미. 그런 물건들이 담은 어둠은 우리 둘을 파괴할 수 있어. 그 때문에 가격이 너무 높다. 내가 죽으면,$B$B내가 원하는 대로 해줘서 둘 다 죽거나 살 수 있겠지만, 이미 설명해줬어"
rows["358:1773074323"]="끝은 가까워지고 있습니다. 지금 우리가 말하는 동안 우리의 물품이 실리투스로 배송되고 있으며 $2113w 일 이내에 도착해야 합니다. 거기에 있으면 모든 사람들이 빠른 순서로 모이게 될 것이라고 확신합니다. 그리고 우리는 전쟁 시작을 위해 아안키라지 문에서  ⁇ 의 울림을 기다리고 있을 것입니다."
rows["358:1892978715"]="육신, 나는 보호국의 사이드 사장이고, 이 병사들은 내 복수자이고, 빈 통을 파괴한 육신에게 명령을 기다리고 있습니다. 그 육신자의 말에 따라, 우리는 디멘시우스의 굴로 올라가서,$B$B너무 오래 됐어... 빈부왕은 곧 우리의 힘을 마주할 거야!"
rows["358:320110551"]="이 신호등을 가져가 적의 기지에 진격하고, 그들의 주요 요새 바깥으로 이동하고, 광경을 정원의 중심에 배치하고, 눈이 신호등의 좌표를 잠금할 때까지 공격자로부터 보호하십시오.$B$B이 작업이 끝나면, 적 기지 밖의 모든 활동은 여기서 볼 수 있을 것입니다.$B$B이 일을 맡아줄래?"
rows["359:1187938220"]="우리는 이 시간의 길이 하이잘 산으로 연결된다는 것 말고는 아는 게 없습니다. 무한의 용군단은 우리가 개입하지 못하도록 막기까지 했었지요. 우리가 알고 있는 것은 거의 아무것도 없습니다, 필멸의 존재여. 소리도르미가 시간의 길의 방어선을 돌파하기 위해 노력은 하고 있지만 아직 별다른 성과가 없었습니다. 방어선을 뚫고 가서 문제를 해결할 이는 당신밖에 없습니다."
rows["359:1451433523"]="우리는 전통적인 방법으로 죽일 수 없는 적을 직면하고 있습니다. 리치 왕의 전염병은 우리 계급 내 어느 치료사가도 억제 할 수 없었던 힘입니다. 포세이큰와 그들의 화학자들은 우리가 가진 유일한 희망입니다.$B$B만약 우리가 이 일을 극복한다면, 호드는 노스렌드로 가서 리치 왕와 그의 군대를 무릎을 꿇게 될 것을 약속드립니다!"
rows["359:1564394874"]="골드린은 고대 늑대이며 호드 언어에서 \"로고시\"로 알려져 있습니다. 그의 끈기는 전설적입니다.$B$B그의 신성지는 월드 트리 서쪽의 한 저수지에 있지만, 그 수호자들은 공격 후 침묵을 마쳤습니다.$B$B우리가 앞으로 나아갈 수 있기 전에, 당신은 성소를 구하고, 고대 늑대의 위치를 발견하고, 그의 적들을 물리쳐야 합니다."
rows["359:1782613674"]="당신이 우리에게 제공한 독소의 샘플에 따르면, 우리는 다음과 같은 것을 필요로 할 것이라고 생각합니다. 미묘한 가속기, 6 개의 뼈의 자극기, 그리고 4 개의 루네클레트.$B$B일단 이 물건들을 가지고 나면, 당신은 카운터 에이전트를 그  ⁇ 에 넣을 수 있어야 합니다."
rows["359:1932638600"]="안녕하세요, 얼라이언스의 동료!$B$B가젯잔의 공식 대표로서, 저는 우리가 가난한 흩어져 있는 기둥들이 가젯잔에서 스팀위들 괴물과 평화롭게 공존할 수 있도록 여기 왔습니다! 우리는 그들의 새로운 호드 괴물 친구들의 존재를 용납할 수 있습니다.$B$B당신 도움으로 우리 모두 좋은 결정을 내릴 수 있을거예요!"
rows["359:805443155"]="밤 엘프들의 전설에 대한 나의 지식은 제한적이지만, 밤 엘프들이 미묘한 마법의 예술을 여전히 신성한 것으로 여겨졌을 때, 아즈샤라는 그 종류에서 가장 위대한 사람이라고 전해졌습니다."
rows["35:1002279052"]="네놈들의 피가 필요하다!"
rows["35:1005867753"]="넌 저주받았어, 우린 치료제야"
rows["35:1006679874"]=" ⁇ 마뱀머리인 네가 치유를 시작해!"
rows["35:1007637377"]="승자가 있어!"
rows["35:1010460200"]="감히 데피아즈단에 맞서려 하다니!"
rows["35:1011937244"]="%s 그리고는 병을 겨냥합니다..."
rows["35:1012182338"]="(주님이 보시고, 주께서는 보십니다!)"
rows["35:1012376060"]="수영장 포니는 뭐하는 거야?"
rows["35:1013444300"]="하루를 당신과 함께 보내면 좋겠습니다."
rows["35:1021806186"]=" ⁇  부의 추락 시나리오를 입력하세요."
rows["35:1027165018"]="영, 내 뜻에 복종하시오"
rows["35:1031405502"]="내가 하는 일이 얼라이언스..."
rows["35:1037344205"]="난 당신의 장갑을 트로피로 가져갈거야!"
rows["35:1039651319"]="이 물건들을 시험해보자..."
rows["35:1041037415"]="모두 손을 올려다!"
rows["35:1041625000"]="%s 반격과 복수"
rows["35:1043693186"]="좋은 소식이 있어, 토키!"
