rows["35:651620826"]="그건 네 문제 아냐, 마구"
rows["35:653064718"]=" ⁇ ... 보스가 기분이 좋지 않아..."
rows["35:653353089"]="더, 더, 더! 당장 먹을 것이 필요하다."
