rows["35:696268670"]="아칸움?"
rows["35:697134152"]="드디어 진정한 운명을 알게 됐어"
rows["35:697644832"]="누가 용기를 내길까? 실로 너희는 멸망하리라"
rows["35:697923694"]="나즈그림과 그의 군대를 봤어?"
rows["35:698721767"]="내 주권민을 보호해야 합니다."
rows["35:701985336"]="안녕, 코아예요. 친구로 해주시겠어요?"
rows["35:704352395"]="두려움에 직면해 증오를 진정시켜라"
rows["35:704561667"]="블랙하프가 널 먼지로  ⁇  거야!"
rows["35:709091709"]="저건 최고의  ⁇ 음악이야!"
rows["35:710817614"]="빨리, 포위 중단해야 해!"
