rows["35:716546396"]="함대에 데려갈 수 있어?"
rows["35:717184199"]="가만히 있어, 곧 끝나는 거야"
rows["35:71790594"]="이건 무슨 일이지? 경비병!"
rows["35:722324015"]="부활 의식은 실패했어!"
rows["35:724963462"]="<사우로크는 애완 동물 뒤에  ⁇ 니다>"
rows["35:726043143"]="잠깐만요, 브랜!"
rows["35:726764444"]="내 끔찍한 피조물 앞에서 몸서리쳐라!"
rows["35:729872414"]="당신은 심각한 미스 스테이크를 만들었습니다."
rows["35:7309297"]="다시 불꽃과 상처로"
rows["35:734620844"]="겨울 히아신스인가요? 제게 주시려고요?"
rows["35:736637882"]="군주님을 위하여!"
rows["35:737955458"]="추운 어둠이 네 영혼을 기다리고 있어!"
rows["35:738013220"]="좋은 정신이 있어 - 내가 받아들일 것 같아"
rows["35:73831458"]=" ⁇  (Melee DPS 도전)"
rows["35:740903189"]="손톱이 부족해"
rows["35:740971196"]="동쪽 탑이 파손되었습니다!"
rows["35:741977144"]="셰크지르 황후가 당신을 파괴할 거야!"
rows["35:74234616"]="이 원숭이에게 박을 줄 거야!"
rows["35:74268561"]="포먼 채권을 어떤 대가를 치르더라도 보호해!"
rows["35:742807365"]="무슨 일이 일어날 수 있어?"
rows["35:745511002"]="흐물흐물 녹여 주마!"
rows["35:750776088"]="고대 검에 대해 뭘 알죠?"
rows["35:758546719"]="더 이상 짚 오크를 날리지 마!"
rows["35:764080793"]="해안을 공격해 그들의 맥주를 훔쳐라"
rows["35:766220156"]="아뇨, 아뇨, 아녜요"
rows["35:769438326"]="$3094W의 활동 중인 왜성들이 있습니다!"
rows["35:771041503"]="황후를 위해 죽는 것은 영광입니다!"
