rows["35:792223318"]="북쪽, 이봐!"
rows["35:793413222"]="이방인들이여, 당신들에게 너무나도 많은 빚을 졌소."
rows["35:802870918"]="본토로 돌아가고 싶어요."
rows["35:804478911"]="으하하! 천둥창은 내 거야. 죽어라!"
rows["35:81347481"]="일어나, 움직여!"
rows["35:816094581"]="혁명에 합류하러 왔어?"
rows["35:819783268"]="그냥 실버문로 이동해"
rows["35:819865120"]="왜 상공이 이렇게 했을까요?"
rows["35:820274484"]="네, 아쉽게 나가 동상을 꺾고"
rows["35:822607928"]="그 사람은 당신 그룹에 부적절해"
rows["35:82475489"]="우리 제국들은 우리의 것을 빼앗아갈 거야!"
rows["35:826348539"]="좋아! 눈 똑바로 뜨고 있게."
rows["35:831363769"]=" ⁇ 은 땅, 황금으로 가득한 땅!"
rows["35:831864283"]="시프가 어떻게 됐는지 말해줄래?"
rows["35:83875160"]="우리 뒤에, 그들은 배를 잡았다!"
rows["35:839280553"]="놀이용 Azure Serpent은 스스로 씹는다."
rows["35:840836076"]="불꽃에서 숨을 수 없잖아"
rows["35:840910970"]="그럼 호크마스터 누롱이 되겠나?"
rows["35:848615526"]="35 아페크시스 셔드를 삽입하고 시작하세요!"
rows["35:851075086"]="더 이상 너에겐 곳이 없어"
rows["35:851535170"]="이것은 시작에 불과하다!"
rows["35:858517268"]="행복한 휴일을 기원합니다, 친구!"
rows["35:860341084"]="다시 데려다줘 다르나서스로 돌아가"
rows["35:863015307"]="가만히 있어 안전장치를 찾아갈게"
rows["35:863662326"]="새로운 제국의 분노를 보라!"
rows["35:863948228"]="지상의 반지는 당신 뒤에 있습니다."
rows["35:864276786"]="너희를 저승의 심연으로 데려가리라!"
rows["35:864508328"]="난 당신 덕분에 너무 많이 성장했어!"
rows["35:86452962"]="부인, 좀 더 낮게 말해주세요."
rows["35:865114629"]="드루이드 곰 모양을 가정해, 투어"
rows["35:865841212"]="%s은 고대 동상을 검색합니다."
rows["35:877867447"]="난 지금 브릴로 가는 비행기를 타고 갈거야"
rows["35:878087001"]="아니, 또 다른 얼굴이 활성화됐어!"
rows["35:881040143"]="우린 내려가야 해 배를 버려!"
rows["35:88248077"]="날려버릴 준비를 해봐!"
rows["35:883883345"]="내 발견된 공알은 어디 있어?"
rows["35:887541580"]="내 기억은 예전의 기억이 아니야"
rows["35:891101794"]="티안  ⁇ 털을 짜는 것에 대해 말해줘"
rows["35:892455670"]="우린 그를 지워버리고 있어 계속해"
rows["35:892923677"]="%s는 워프 재저의 피를 수집합니다."
rows["35:893278475"]="위험금으로 돈을 벌게 될 거야"
rows["35:89672882"]="오, 신여, 그들은 여기 있어요!"
rows["35:898306727"]="저 놈을 죽여라!"
rows["35:900987090"]="아, 그래. 로켄이라면 잘 안다."
rows["35:906299041"]="와일드햄어한테 한 번 더!"
rows["35:906371308"]="죄를 고백하고 용서받아!"
rows["35:908207035"]="적의 발길이 강해..."
rows["35:908943568"]="이 흔적은  ⁇ 고의 거야"
rows["35:909712287"]=" ⁇ 은 잠금 풀음 소리가 들리네요"
rows["35:91328550"]="그럼, 박사님 연구 결과가 어떠세요?"
rows["35:91481753"]="롤빵, 작은 롤빵, 식빵 있어요. 갓 구운 빵입니다!"
rows["35:919479760"]="아즈히르 감시자가 널 발견했어"
rows["35:919720740"]="납치자들을 얘기해줘"
rows["35:920998416"]="넌 코크론을 이길 수 없어!"
rows["35:921539207"]="호드는 워디언의 비지일을 잡았다!"
rows["35:922864704"]="방해를 시도하는 모든 사람을 죽여라!"
rows["35:923463389"]="너무 안일해져서는 안 되지."
rows["35:923708280"]="알아낼 방법은 하나밖에 없는데"
rows["35:930089081"]="이 병을 스스로 치유해봐!"
rows["35:933503745"]="아가마스 게이트를 침해한 거야"
rows["35:937124333"]="무역 구역에 있는 유니스 버치"
rows["35:938141904"]="다 됐소! 어서 몸을 숨기시오!"
rows["35:938736472"]="우린 악인을 찾고 있어"
rows["35:939560989"]="난... 내가 못 올 것 같아"
rows["35:93986573"]="몇 가지 질문이 더 있어"
rows["35:943506004"]="함께 뭐든 할 수 있어, 안렌!"
rows["35:94386716"]="프로스트맨 레이더, 경보를 불러!"
rows["35:952502892"]="내가 살아 있는 사람들로 돌아왔어"
rows["35:959370035"]="아무도 빅G를 공격하지 않고 살지 못해요!"
rows["35:966532327"]="하이 ⁇ 로드 포드링, 괜찮아?"
rows["35:969231876"]="난 갇혀 있어 조심해"
rows["35:970967098"]="제로미는 술에 취해서 잠들게 됐어"
rows["35:972115969"]="아킬다라, 내 동맹국에게 돌려줘"
rows["35:975316611"]="어서, 다다나가!"
rows["35:975859199"]="그만해, 방해는 그만해!"
rows["35:976448462"]="%s 잃어버린 영혼에 대한 기도입니다."
rows["35:978136266"]="하지만 미스터스, 아드미랄은..."
rows["35:989371984"]="아아아... 속이... 안 좋아..."
rows["35:994476427"]="여기 있습니다. 스톰스타우트 맥주 공장입니다."
rows["35:995407940"]="자즈오 구출에!"
rows["35:995942966"]="내 여동생의 죽음으로 갚을 거야!"
rows["35:99639907"]="진실 한 사람 호드 원하는 걸 가져가야 해!"
rows["35:9969837"]="맛있는 맛을 먹을 수 있는 건 뭐죠?"
rows["35:99989919"]="돌고래에게 먹이를 먹여라"
rows["360:1571210764"]="얼마나 멋진 표본을 잡았는지요. 전기를 사용하지 말라고 가르쳤어요. 아직 갓 태어난 아이이지만,$b$b다행히 저 곳의 태양보행자는 그러한 악행에 의해 부상당한 사람들을 치유하는 데 매우 도움이되었습니다.$b$b그리고 난 네 작은 생물에게 이름을 붙여주게 된 자유도 가져갔어"
rows["360:1850166959"]="아직도 파멸의 인도자만 찾으면 어떻게든 전세를 역전할 수 있다고 생각하시오? 사령관, 자네에게 작은 비밀을 하나 알려주지. 파멸의 인도자가 내는 힘은 그것을 사용하는 사람에게서 나오는 것이오... 사령관, 나는 그곳에 있었소. 그가 검을 뽑기도 전에 정의로운 불길이 언데드 군대를 활활 태우는 모습을 보았단 말이오. 슬프군. 당신은 역사에 대한 이해력이... 조금 부족하구려."
rows["360:19274595"]="많은 학생 들 이 이전 에 배운 모든 것 을 철저 한 재교육 을 통해 다시 가르치기 위해 깨뜨려야 했습니다. 제가 제공하는 봉사 는 수행 할 때마다 점점 더 어렵게 됩니다. 이 이유 때문 에 재교육 한 번 마다 점점 더 비싸게 됩니다."
rows["360:579972401"]="거의 아무도 없습니다. \"골든 로터\"라는 그룹이 지키고 있습니다. 골든 로터의 구성원들은 천연들이 골든 로터에 대한 경비를 유지하도록 손으로 선택합니다.$b$b난 어린 시절부터 밸리에 대한 이야기를 들었어요$b$b수영장의 전설이 사실이라고 생각하십니까?"
rows["360:677011667"]="레이  ⁇ 은 자신의 힘을 다할 수 없게 해줘야 합니다.$b$b앞문들을 공격하는 데 시간이 필요하고, 당신의 얼라이언스와 호드의 도움도 필요하지만 우리가 아는 한 가지 있다면$b$b터널 뒷쪽의 하수도들은 요새 입구까지 이어집니다."
rows["360:769055613"]="디폴름 은 느리고 조용 한 곳 이었다. 항상 살아있으며, 끊임없이 움직이고 있었습니다. 결코 서두르지 않았습니다. 이 기간 동안, 저는 지구와 하나가 되기 위해 노력했습니다. 그리고 어느 정도 성공했습니다.$B$B나중에 지구워더가 부상을 입고 돌아왔는데, 처음에는 균형을 깨지 않았습니다. 그는 전에 이곳에 머물렀고, 우리는 그를 알고 있었습니다."
rows["361:1123658832"]="아니, 그 곳도 아니죠. 여기 어딘가에 있을 것 같네요. 그건 그렇고, 그 냄새가 나는 구석에서 빠져나가는 것이 얼마나 멋진지 언급했나요?"
rows["361:1740398641"]="판드리아크들은 내 장남을 축복해줬어요$b$b아무에게도 말하지 마, 하지만 그 때문에 고마워요.$b$b하지만 우리는 너무 정해진 방식이었고, 우리의 차이점을 극복하기 위해 새로운 무언가가 필요했습니다."
rows["361:1850165155"]="넌 누구야, 작은?$B$B내가... 널  ⁇ 어야겠어!$B$B하지만 당신은 내 미련에서 나를 구해줬어.$B$B내가 너한테 시프라고 생각했을 때 우연이 아니었어$B$B그녀의 죽음을 복수하고 타이탄들의 신성한 땅을 내 동생의 미쳤음으로부터 해방시켜야 합니다!"
rows["361:404920075"]="<젠타브라는 눈을 감고 머리를 흔들고 있다>$B$B볼진이 모든 사람들을 도망쳐달라고 부르자 우리는 부족에 맞서기 힘들었고, 그래서 남쪽으로 도망쳐서$B$B야생의 첫 밤 몇 개 '우리' 주장. 우리는 섬의 중심에 깊은 동굴에서 안전을 찾았다, 하지만 내 꿈은 평화로운 것이 아니었다:"
rows["362:1040272469"]="자이나 프라우드무어는 이제 키린 토르의 지도자로 앉아 달라란을 통치합니다.$b$b이 때문에 에타스는 중립성에 대해 얼마나 자랑하든, 성곽 광장은 얼라이언스의 손에 맡겨집니다.$b$b이 젊은 신흥은 잊었을지도 모르지만 얼라이언스는 제3차 전쟁 때 우리 사람들을 감옥에 가하고 학살하려고 시도했습니다.$b$b그들의 중립성에 대한 그의 믿음을 공유하지 않는다면 용서해 주십시오."
rows["362:617284619"]="검은 용 비행에 대한 우리의 역사를 알고 있지 않나요? 오닉시아 그래서 래티온을 찾아왔지$b$b<안두인'은 탁자 건너편에서 그의 특이한 동반자를 쳐다보고 있습니다.>$b$b하지만... 다른 검은 용들과는 다르지 않죠? 그는 완전히 정직하고 항상 뭔가를 숨기고 있습니다."
rows["362:826458239"]="이 계곡이 얼마나 평화롭고 아름답는지 전까지 들은 이야기들 뿐이야. 우리 중 어느 누구도 들어가지 못했을 때, 이제 우리가 여기 왔으니,$B$B그래서 이야기는 거짓말인가, 아니면 우리가 그저 끔찍한 모임인가? 저는 겸손히 이 가능성에 대해 제 자신을 배제합니다. 왜냐하면 그런 것을 고려하는 것은 어리석은 일이기 때문입니다."
rows["363:1103660911"]="키린'바르는 20 오랜 세월이나 무수히 많은 오크 공격을 살아남았지만 카엘타스의 세력을 견딜 수 없었다. 한때 자신을 키린 토르의 일원이라고 부르는 한 남자가 한 명을 제외하고 우리 모두를 살해했다.$B$B아르크메이지 바르고트는 공격을 살아남았기 때문에 카엘타스는 그를 바이올릿 타워 안에 갇혀 키린 타워의 통과를 금지하는 마법으로 보호했습니다."
rows["363:1435646473"]="많은 사람들이 생각했던 것보다 더 끔찍한 상황입니다. 포세이큰는 우리 공통의 적인 스컬지와의 싸움에서 동맹국으로 여기 있습니다.$B$B내가 이렇게 말할 때 믿으세요, 그들 없이는 귀신국들은 사라지고 스컬지는 이미 에버송 우즈 전체를 점령했을 것입니다!$B$B하지만 무엇보다, 우리는 당신의 도움이 필요해 한때 자랑스러운 땅을 되찾는 데!"
rows["363:1954156439"]="이 캠프 북동쪽에는 크로시우스라는 강력한 지옥이 있습니다. 니비가 여기 있는 이유입니다. 크로시우스라는 더 큰 지옥입니다. 예상보다 더 오래 지속되었습니다."
rows["363:2094288795"]="감정도 없고 도덕도 없고 열정이 없습니다.$B$B형제단만 존재합니다.$B$B여기, 빛의 전달자 우더가 은손의 질서에 가입한 예배당에서, 나는 빛의 챔피언인 코르팩스, 무경한 사람들에게 두려움을 불러일으키겠습니다.$B$B내 분노를 억제할 수 있는 것은 아무것도 없습니다 붉은십자군아르헨트 Dawn, 내 형제들, 심지어 너도 아니었어"
rows["364:1231106145"]="네더가르드의 감시자들은 포털에서 혼란을 감지하고 악마들이 우리 세계에 울려 퍼지기까지 시간이 얼마 남지 않았다!$B$B아제로스의 왕국으로부터 보강이 도중에 있지만, 우리는 아르헨티나 새벽에 속한 사람들이 네더가르드의 요청에 먼저 동참했습니다.$B$B우리의 임무는, 얼라이언스와 호드의 도움이 도착할 때까지 이 괴물을 배에서 지켜야 합니다..."
rows["364:1539580294"]="텔레도르 는 한때 드레네이 사제 들 과 순례자 들 이 찾는 고립적 인 피난처 였으며, 그 곳 의 사제 들 은 거의 방문 을 받지 않았다.$B$B오크들이 드레네이 정착지를 공격하기 시작했을 때 난민들이 더 많은 수의 사람들이 도착하기 시작했습니다. 아코르이트 아우른과 다른 사람들은 테일로더를 성소에서 안전한 항구로 바꿨습니다. 나 자신도 포함해 많은 드레네이들은 그의 노력에 우리의 생존을 빚어집니다."
rows["364:1776763791"]="끝은 가까워지고 있습니다. 지금 우리가 말하면서도 우리의 마지막 물품들이 실리투스로 보내지고 하루 안에 도착해야 합니다. 거기에 있으면 우리는 모두 빠른 순서로 집결될 것이라고 확신합니다. 그리고 나서 우리는 전쟁 시작을 위해 아안키라지 문에  ⁇ 의 울림을 기다리고 있을 것입니다."
rows["364:32994330"]="젊은 마스터가 했던 극과 혼란은... 세상의 운명이 그의 어깨에 달려 있다고 생각하겠죠.$B$B아쉽게도 그는 저한테 그의 소소한 마법의 비밀과 무지한 것들을 남겨뒀어요."
rows["365:1268636701"]="아타스가 프로스트모른을 잡았을 때 버려진 해마르에는 큰 잠재력이 있습니다.$b$b이 세상 의 운명을 결정 한 사건 을 일으키는데 도움 이 되었습니다.$b$b충분한 사로나이트를 가지고 해마를 재조형으로 만들 수 있어 프롤스트모른과 경쟁할 수 있습니다.$b$b그 때 가장 위험한 재판이 시작됩니다."
rows["365:1907321436"]="고르도니족은 페라라스의 상당 부분의 숲을 통제하는 큰 오그르족입니다. 그들의 어두운 마법은 그들을 둘러싼 요소에 침투하여 환경과 그 안에 사는 생물 모두에게 피해를 입습니다.$B$B페라라스로 여행을 떠나기로 결정한다면, 이 오그르들을 조심하세요. 그들은 꽤나 불쾌하고 많은 사람들이 강력한 암흑 마술을 할 수 있습니다. "
rows["365:1915288155"]="진정한 믿는 자들은 스케티스에서 우리의 배신적인 사촌들이 우리로부터 책을 훔쳐서 그 표지를 깨고 그 조각들을 그들의 비참한 도시에서 묻은 날부터 부끄러움을 겪었습니다.$B$B내 아들아, 까마귀가 너를 다시 데려오도록 기도해줘"
rows["365:2077061185"]="저는 가로쉬가 준비가 되어 있다고 생각했습니다. 워시프의 장막이 그에게 관점을 줄 것이라고 생각했습니다. 우리 국민들이 직면한 많은 문제들 중, 그는 하나의 해결책을만 보았다. 호드에 대한 그의 비전은 우리를 가장자리에 데려갔습니다.$b$b이제 새로운 방향이 필요해 볼진은 우리를 데려갈 거야"
rows["365:81308322"]="그래서... 초이 말하는 낯선 사람이 바로 너야$b$b난 페이지 골드엔드라프트 그리고 내 가족은 파다리아에서 가장 좋은 맥주를 만들죠$b$b그 와더브레와 달리, 그들은 항상  ⁇ 마스터의 명성을 망치고 있습니다. 저는 어린이를 내 딸을 감시하는 걸 간첩한 것 같습니다."
rows["366:1240942792"]="뭔가 이 검은 철 Dwarvess 분노를 일으켰습니다. 그들은 거의 반 시간마다 나타납니다, 모든 배를 깨고, 떠나!$b$b그래서 아마 \"왜 내가 신경 써야겠어?\"라고 묻겠죠.$b$b내가 말해줄게... 그들이 깨는 배는 우리가 무료  ⁇ 을 줄 수 없으니까!$b$b그래서 만약 당신이 이 왜자들이 나타나면 주변에 있다면, 잠시 시간을 두고 배들을 보호해 주세요."
rows["366:871227137"]="나도 몰라요$b$b내가 방금 공중에서 화학물질을 전달하는 로켓을 만들려고 돈을 받았고, 그게 내가 한 일이야. 일 끝났어, 친구. 그들은 모두 만들어지고 포장되어 발송되었습니다."
rows["367:1077523775"]="선택의 여지가 없었고, 그렇게 생각했지. 난 타우리산의 파괴를 견디고, 내 왕과 그의 백성의 편에 서게 될거야.$B$B라그나로스의 지배 아래, 다그란 타우리산 왕은 이 산의 심장을 찢어내고 블랙록 스파이를 세웠고 우리는 그 이전이나 그 후의 도시나 요새보다 더 강력한 왜성 도시를 건설하기 위해 끊임없이 노력했습니다."
rows["367:1176277133"]="블래스텐하이머 5000 울트라 캐논은 최첨단 단인 발사 장치입니다.$b$b용의 속도에 가까운 속도로 운반되는 이 대포는 항공기 및 연연력으로 세계적으로 유명한 블래스텐하이머 가족의 자랑과 기쁨입니다!$B$B만약 당신이 하늘을 날아다니는 새처럼 자유롭게 날아다니고 싶다면, 맥시마 블래스텐하이머를 찾아라."
rows["367:1541340870"]="5개의 측면의 결합된 힘으로 알려지지 않은 존재에 대한 하나의 전설적인 켈레서라 블레이드가 있다고 소문들이 있습니다. 네파리안과 죽음의 날개의 혐오가 우리 세계에 투입되기 전에, 그러한 측면의 만남은 '프리스마틱'이라는 용어로 표현되었습니다. 나는 단지 킬레서라 프리스마틱 블레이드는 가장 영광스러운 창조라고 가정 할 수 있습니다.\010"
rows["367:1962252208"]="마지막 재료는 가족들의 세대에 걸쳐 전해 내려온 비밀입니다. 크라사랑 야생지에서 온 것입니다. 저는 몇일 전에 부자키 비서에게 그것을 가져오도록 보냈습니다. 그리고 어제 밤 霧の中の 술집에 도착했다고 들었습니다. 당신은 고대 통로를 향해 가서 그를 붙잡고 있는 것을 알아낼 수 있습니까?"
rows["367:773856131"]="로카르 오가르, 승리와 죽음이 호드왜냐하면 그들은 세계 모든 전쟁에 있어서 가장 신성한 진리이고 호드.$B$B난 내 피와 육체를 전쟁의 장군에게 자유롭게 바치고 난 나의 전쟁의 장군의 욕망의 도구이고 난 나의 전쟁의 장군의 지휘의 무기입니다$B$B이 순간부터 마지막까지 나는 살아 죽는다 - 호드를 위해!"
rows["367:886416922"]="내 형제들은 강하지만 내 형제들은 비역자입니다.$B$B변화 는 움직임, 분쟁, 폭력 이 없으면 일어나지 않습니다. 우리 의 적 들 은 이 일 을 잘 인지 하고 있든 없든 경험 합니다. 우리 형제 들 의 비활성성 은 그들을 이 새로운 적 들 에게 약하고 취약 하게 만든다.$B$B내가 아니라, 난 변화를 두려워하지 않을거야. 나는 땅을 찢어지고 산을 움직일거야. 나는 변화를 받아들이는거야."
rows["368:1028148825"]="<이트리그가 웃는다>$B$B젊은 사람, 세상은 항상 그런 혼란에 빠진 적이 없습니다. 그것은 스컬지이 땅을 약탈하기 전의 시간이었습니다. 로데론의 그 지역이 Plaguelands라고 알려져 있기 전에.$B$B그 때  ⁇ 은 날 죽음으로부터 구해줬고, 그때 내가 새 호드에 합류했지... 하지만 나는 물러나서고 있다."
rows["368:34623181"]=" ⁇ 이키에게 도움이 될 거야. 그는 생각 중이야. 우리는 아안키라지 전쟁에 대비하기 위해 불꽃 약물의 엄청난 양을 필요로 할거야. 호드'Pele'keiki, 우리한테 $2051w 불꽃잎의 발자국과 함께$B$B펠레키키가 지금 말해, 그는 단지 $2050w 불꽃, 하지만 당신은 곧 그것을 추가 할거야, 맞지?"
rows["368:49320742"]="서쪽으로 탐사 임무에서 많은 풍력 승무원들을 잃었습니다. 스컬지는 스파이가 될 수 있는 공격에 무자비합니다.$B$B다행히도, 나는 라이더의 생명을만 위험에 빠뜨리는 솔루션을 생각해냈습니다. 그것은 나사무 평야를 가로질러 운항하는 사람들에게 30%의 생존율을 보였습니다. 그것은 우리가 풍력 라이더를 사용했을 때보다 30%의 개선입니다!"
rows["368:852857194"]="그 큰 악귀 트롤을 이렇게 땅에 치는 것은 참 놀랍고 난 이 구석의 손잡이를 못 잡았는데 너무 미안해 그렇지 않으면 뛰어들어 다른 죄수들을 죽이고 날 겁에 내렸다고 다시 돌려받기 위해 그를 찢어버리겠군"
rows["369:1071079692"]="이 해안에서 보이는 것은 스컬지의 결과가 아닙니다. 사실, 우리는 스컬지도 안개가 두려워한다고 믿습니다. 그래서 그들은 여기 오지 않을 수도 있습니다.$B$B안개가 살아있어요, 친구. 그 공중의 톱니 안에 죽음이 있습니다.$B$B그 안의 손에 들어가면 사라질 거야 안개가 널 데려갈 거야$B$B우리는 아무도 안개에서 살아 돌아오는 것을 본 적이 없습니다."
rows["369:1339159402"]="너무 추워서 배고프다$B$B내 가난한 친구, 네가 평화를 찾았으면 좋겠어$B$B넌 거기 있어 제발 날 도와줘요. 한 명은 열쇠를 가지고 있어, 찾을 수 있어? 내가 알아, 그들이 가지고 있어."
rows["369:1589658955"]="오래전, 마지막 전쟁 전에, 아버지는 노스리지 목재 공장을 운영했습니다. 그것은 그의 삶이었고 그는 그것에 헌신했습니다. 스톰윈드.$B$B그 시절 우리는 많은 친구들과 가족을 잃었고, 붉은십자군가 그 공장을 자기 목적에 취했다고 아는 것이 고통스럽습니다.$B$B그래서 돌아왔어요"
rows["369:1672358839"]="안녕하세요, 좋은 여행자 이 훌륭한 괴물은 오늘 당신을 위해 무엇을 할 수 있습니까?$b$b저는 제가 빛의 희망 사당에 있는 이유는 단지 이 아르헨티나 십자군들과 공유하는 스컬지에 대한 증오 때문이고, 확실히 제펠린 충돌에서 도망치는 것이 아니기 때문입니다!$b$b더 더 많이 관여하기 전에 말 그만해!"
rows["369:1695557414"]="내 동생과 저는 실바나스에게 헌신했습니다. 그녀는 가장 어두운 때 우리의 빛의 신호등입니다. 우리는 우리 종들이 우리를 선택한 운명을 극복하기 위해 매일 희생합니다.$B$B우리는 약해지지 않을 것입니다. 우리는 우리에게 빚진 것을 가져갈 것입니다. 우리는 우리에게 당한 고통을 열 배로 돌려 줄 것입니다. 우리는 우리의 얼굴에 미소를 가지고 그렇게 할 것입니다."
rows["369:2011418870"]="이코는 모든 생물들이 가진 힘이고 내가 당신을 위해 만든 매력은 물리적인 표현으로 그것을 포착할 수 있게 해준다.$B$B내가 알아, 마법은 당신이 발견한 다에코를 변해 주주로 바꿀 수 있다는 걸$B$B마우아리의 캐시를 가져가서 자기 자신에게 주주의 힘을 반영해 줄 수 있다.$B$B어서, 시도해봐, 다코 타 마우아리를 데려와, 좀 즐겁게 해"
rows["369:2027171501"]="벤처기업의 새로운 셔더는 내 최신보다 더 낫습니다. 교환 가능한 손에서 제어잡이에 이르기까지!$b$b제 보스가 제게 아주 엄격한 임기를 내놨지만, 저와 제 친구들이 아무것도 찾지 못했어요. 아무 것도 작동하지 않았기 때문에 그들의 프로토타입 중 하나를 \"부채로\"하기로 결정했습니다. 저는 Wizzlecrank을 슬러지 Fen에 보내서 훔쳤어요. 하지만 그는 아직 돌아오지 않았습니다."
