rows["36:751238353"]="네놈 몸뚱이로 장화나 닦아야겠다!"
rows["36:75779393"]="누가 코로트의 깃발을 만질까?"
rows["36:758952553"]="우린 널 보호해, 이제 반발!"
rows["36:760337366"]="우리의 처벌은 또한 우리의 축복입니다."
rows["36:771418121"]="너희 늑대들은 쓸모없어"
rows["36:772616176"]="그리고 어떤 타락한 이유가...?"
rows["36:77479425"]="걱정 마, 곧 다 끝나게 될 거야"
rows["36:778514949"]="내 재능은 이 쓰레기에 낭비됐어"
rows["36:779020272"]="아콜론은 전투장에 들어왔다!"
rows["36:779506918"]="내가 한 것 중 최고의 실험이 될 거예요!"
rows["36:781130300"]="난 당신 전화로 왔어, 돌모아"
rows["36:782937610"]="좋습니다, 듀로탄의 아들 스랄이여."
rows["36:78515353"]="저기, 앞쪽은 얼라이언스 폭탄 테러가!"
rows["36:78786798"]="%s 그가 아프게 될 것 같네요!"
rows["36:788150441"]="좋아. 희생양이 하나 늘었군."
rows["36:788748532"]="너희 영혼은 끝없는 고통을 알게 될 것이다!"
rows["36:789801577"]="벌떼들이 불을 싫어하는지는 몰랐는데!"
rows["36:790923655"]="수호자가 깨어났어!"
rows["36:793657086"]="꽤나 웃긴 것 같네요"
rows["36:795833891"]="거의 모든 군대가 여기 있을 겁니다"
rows["36:796707607"]="안 돼! 제발 부탁이오! 날 죽이지 마시오!"
rows["36:797454218"]="파라곤, 클라엑시 침투자!"
rows["36:8031673"]="약점, 이 왜자들은 아무것도 아니야!"
rows["36:808684398"]="아이시미스트 마을에서만 비행할 수 있습니다."
rows["36:81394983"]="땅이 당신 밑에서 울리고 있습니다."
rows["36:815944682"]="이 코도들은 놀라운 상태입니다."
rows["36:816399083"]="구버, 낚시봉은 없어요"
rows["36:828848540"]="네 목숨은 여기서 끝이다, 바위의 동맹 녀석!"
rows["36:831067163"]="술 좀 마실 필요 없어"
rows["36:832131304"]="가로쉬의 착륙으로 보내야 해, 야니"
rows["36:834012673"]="평평한 호랑이의 뒷면에 다시 가!"
rows["36:83420686"]="내가 무슨 일이 있었는지 모르겠어"
rows["36:834304661"]="내 뒤를 따라가, 죽음이 가까워"
rows["36:834608248"]="네 피를 제물로 바칠 것이다."
rows["36:836983606"]="이 호드 맛을 낼 거야 얼라이언스 철강!"
rows["36:837002010"]="얼라이언스 다리는 공격당하고 있습니다!"
rows["36:837690759"]="일어나라, 부하들아! 지나가게 하지 마라!"
rows["36:837709048"]="뱀이 내 쟤들한테"
rows["36:837796285"]="...하지만 여기 영원히 남아있을 것입니다."
rows["36:840091767"]="비행기에서 벗어나, 똥구리!"
rows["36:840110346"]="내가 널 그렇게 할 수 없게 해, 가로쉬"
rows["36:841668145"]="오한제 장로는 군드라크에 있습니다."
rows["36:845333102"]="북부 로켓웨이 터미널, 부탁드립니다."
rows["36:845748158"]="지옥의 눈은 너희 위에 있네!"
rows["36:852450953"]="머리도 잘 어울리네요"
rows["36:856974670"]="피닉스처럼, 나는 되살아난 자 될 것이다."
rows["36:858703756"]="누가 더 큰 숙련자가 있는지 보자."
rows["36:860234426"]="그림토템 부족이 더 많이 몰려오고 있어요!"
rows["36:863514345"]="호드은 타이탄 포털을 점령했습니다!"
rows["36:86413404"]="글린트록 스카우트는 경고를 외치고 있어요!"
rows["36:868557187"]="이게 바로 개구리 스타일이지!"
rows["36:870449561"]="위쪽 발이 험한데 조심해"
rows["36:877713937"]="%s 그의 불행에서 벗어날 것을 빌고 있습니다."
rows["36:879427818"]="남쪽 로켓웨이 터미널, 부탁드립니다."
rows["36:880488020"]="%s은 호디르의 희귀한 캐시를 파괴합니다!"
rows["36:884729954"]="드디어 네 시간이 왔어, 고드프리!"
rows["36:8929365"]="계속 오고 있어!"
rows["36:897518225"]="오직 한 명의 워시프만 있어, 에이트리그!"
rows["36:90213821"]="그러면 이동하자! 이동..."
rows["36:90298428"]="벽에 올라갈 수 있는 비행기가 필요해요!"
rows["36:906641565"]="아닐세, 내 오랜 친구여. 관련이 아주 많다네."
rows["36:90743148"]="네 선택의 기미오리를 보여줘"
rows["36:90785353"]="그게 다야, 마녀장님?"
rows["36:908951005"]="요소들은... 우리가 뭘 했지?"
rows["36:910614787"]="오프, 더 좋아... 내 머리카락은 어때?"
rows["36:911189964"]="엘루네의 빛... 그 물건은 뭐죠?"
rows["36:911198083"]="이와크 풀 크스근 온마 예글루 주."
rows["36:918318280"]="하카르는 점점 더 무감하게 되고 나도 마찬가지입니다."
rows["36:925388958"]="다시 테스트를 할 수 있나요?"
rows["36:929891472"]="결국은 파멸을 향해 치닫는구나!"
rows["36:930948731"]="역겨운 트로그놈들. 죽어라!"
rows["36:932084997"]="그냥 상자 안에 돈을 두고 가"
rows["36:933282176"]="%s는 울색한 양을 반복적으로 찌르고 있습니다."
rows["36:933495204"]="서쪽 다리는 손상됐어!"
rows["36:933665"]="그렇게 원한다면 다시는 앞을 못 보게 해주지."
rows["36:950354370"]="3등급 진단 실행 중..."
rows["36:950607701"]="야롱에게 무슨 짓을 했니?"
rows["36:954448788"]="전투는 15초에 시작됩니다."
rows["36:955884147"]="얼음 피 묘지를 누가 통제하고 있어?"
rows["36:959934382"]="이 괴물들로부터 안전한 곳이 없나요?"
rows["36:959935797"]="하프힐로 돌아가자, 무드무그"
rows["36:965974173"]="내 영원한 감사가 있어 영웅"
rows["36:970119444"]="왜 펄브로우가 죽였어?"
rows["36:970557731"]="그들 중 한 명도 살지 못하게 해"
rows["36:972569959"]="표면 아래에서 많은 것들이 숨어 있습니다."
rows["36:979373472"]="%s는 이해할 수 없는 말을 합니다."
rows["36:980068772"]="내가 하는 일이 호드..."
rows["36:981095073"]="뭐, 저한테 돌려보내려고?"
rows["36:983247434"]="대지가 네 피로 붉게 물들리라!"
rows["36:990249006"]="넌 강해!"
rows["36:992789722"]="제 계급을 높이기 위해 싸우고 싶어요!"
rows["36:993837648"]="잘했네. 이 일을 마무리짓도록 하세."
rows["370:738578605"]="도착한 걸 알 수 있어 \010$b이것은 해가 끝날 날의 날입니다. 영원한 우물 붕괴가 세계의 대륙을 찢어 놓았을 때입니다.\010$b여기서 우리는 드래곤 영혼이 시간의 흐름을 잃기 전에 그것을 잡을 것입니다.\010$b하지만 먼저 아즈샤라의 래키들의 보호 구역을 내려놓아야 하니까 궁전 안에 찾을 거야\010$b행운을 빌어, 영웅들!"
rows["370:997258897"]="지금 이 지도자에게 계획대로 진행되는 상황을 보고하고 있습니다. 몇 주 더 걸릴 때만 이 곳은 다시 정형이 될 것입니다.$B$B하지만 그림자 협의회는 오크들로만 마을을 구성해 줄 수 있어 조상들의 주장을 할 수 있고 비밀리에 일할 수 있을거야$B$B잠깐, 내가 당신을 알고 있나요?"
rows["371:1132204320"]="밤의 축복이 당신에게 있기를 바랍니다, 친구! 나는 이리야나 문블레이즈이고, 나는 잿빛 골짜기에서 은 날개 세티넬의 주요 공급자입니다. 당신은 세티넬의 지위를 향상시키면서, 나는 당신에게 화성 골치 안에서 사용할 수 있는 좋은 상품을 제공 할 것입니다. 당신이 아이템 수리 필요를 발견하면, 나는 또한 그 서비스를 제공합니다."
rows["371:1163629365"]="저는 언더시티의 인구조사에서 근무하는 도시 공무원입니다. 우리 는 스컬지에서 해방 된 이래로 우리 도시 인구를 정확하게 추적하려고 노력했습니다. 미묘한 방법과 날카로운 정신적 징계로, 저는 이 기록에 액세스 할 수 있습니다. 따라서 저와 관련한 사업을 한다면, 계속하십시오. 당신이 할 경우, 적어도 알아야합니다."
rows["371:121697518"]="여기 보드에 두 개의 주요 법안이 있습니다. 하나는 파파 휠러의 법안이고 하나는 로켓 체프의 법안입니다.$B$B아빠가 원하는 기계 부품 광고처럼 보이는데, 로켓 상장은 거대한 산 거리의 머리 상금과 관련이 있어요!$B$B두 가지의 세부 사항은 매우 작은 괴물 필사에서 제공되어 있습니다."
rows["371:1396325626"]="6명의 부교도들이 전선 방어력을 통제하고 있습니다. 그들은 먼저 파괴되어야 합니다.$B$B만약 모든 중위들이 순차적으로 죽여지면 전선의 도덕은 흔들릴 것입니다!"
rows["371:1733691436"]="현재 시간의 길은 가장 안정적인 것에서 가장 위험한 것의 순서로 분류되어 있습니다. 시간의 길이 위험도에 따라 분류되었다는 사실을 꼭 기억하시기 바랍니다. 시간의 길 중 한 곳이 붕괴되면 당신의 세계가 종말을 맞이하게 되니까요. 우리는 이곳에 오는 영웅과 모험가들이 어떤 시간의 길이 자신의 능력에 맞는지 쉽게 인지할 수 있도록 하기 위해 그런 방식으로 시간의 길을 분류한답니다."
rows["371:329072636"]="이 비밀들이 당신 같은 필사자에게 알려지는 것은 성스러운 행위로 국한되어 있지만, 저는 선택의 여지가 거의 없습니다.$B$B타이탄의 딸 프레이아가 날 떠난 이후로 한 가지 임무만 해왔고 실패할 수 없다.$B$B이 곳을 이 곳과 비슷한 다른 곳으로 연결하는 게이트가 있습니다. 우리가 찾는 무기도 거기서 찾을 수 있습니다."
rows["371:459191610"]="나무가 죽고, 키파리 보르는 이미 죽은 채로 셰의 희생자이고, 더 이상 황색을 생산하지 않을 것이고, 나무처럼 보이지 않을 것이다.$b$b남긴 양황을 생산하는 나무들은 마티드에게 과잉 채취되거나 셰에 굴복할 위험에 처해 있습니다. 어쨌든, 더 많은 수액은 더 많은 수액의 주인이 아닙니다. 그 시점에서, 나는 이전 일에 돌아가야 할 것입니다."
rows["371:848751438"]="로데론의 노력은 모두 헛되이 되었어요. 수많은 역경에도 불구하고, 스컬지는 여전히 불완전합니다. 우리는 그 원천에서 그들을 끊어야 합니다.$B$B노스렌드 항해가 다가오고 있습니다. 우리가 무엇을 기다리고 있는지 모르겠지만, 우리의 적들이 많고 우리를 학살하기를 간절히 원한다는 것뿐입니다.$B$B하지만 우리는 깨끗한 양심으로 다른 길을 갈 수 없습니다. 아제로스 우리의 경계심에 달려 있습니다."
rows["372:1959678524"]="저는 아들 안지를 언덕 아래에서 채소 농장을 관리하도록 했습니다. 제 조카인 리앙은 서쪽으로 돼지 농장을 운영하고 있고, 그의 아버지인 내 동생은 그 남쪽에 작은 양농장을 운영합니다.$b$b농부 시절은 끝났어 요즘은 수확을 모으고 이 길을 가는 사람들에게 팔아먹는 거야"
rows["372:247688860"]="이국 국민 스톰윈드죽음의 날개는 사라졌어요! 재앙은 끝났어요. 용감한 영웅들이 치명적인 정확성과 압도적인 힘으로 파괴자를 공격했고, 드래곤 애스펙트에게 그들의 힘을 희생할 기회를 제공했습니다. 스톰윈드 미래에 대한 희망의 신호등으로 봉사 하기 위해서요!"
rows["372:276652181"]="울두아르, 울두아르를 지키겠다고 맹세했지$B$B창작자의 테라스를 지키겠다고 맹세했지$B$B얼음의 종족들 사이의 조약을 지키기로 맹세했지$B$B하지만 실패했어요. 제 동생이 저를 속이고, 제 동맹군들을 향해 저를 돌리게 했습니다. 그는 저를 속이고, 시프의 죽음을 내 친구인 얼음 거대들의 왕인 아랑그림에게 비난하게 했습니다.$B$B내가 뭘 했는지 깨달은 후 절망에 빠졌어요"
rows["372:455642587"]="이국 국민 오그리마죽음의 날개는 사라졌어요! 재앙은 끝났어요. 용감한 영웅들이 치명적인 정확성과 압도적인 힘으로 파괴자를 공격했고, 드래곤 애스펙트에게 그들의 힘을 희생할 기회를 제공했습니다. 오그리마 미래에 대한 희망의 신호등으로 봉사 하기 위해서요!"
rows["372:97299761"]="안녕하세요 여행자, 거의 여기 있었습니다 1,000 몇 년 전, 키라지족이 칼림도어.$B$B전쟁 중에 수천 명의 목숨을 잃었고, 대부분 이 저주받은 사막에서 처음 침략 때였습니다.$B$B저는 과거와 현재에 묶여 있는 몇 안 되는 사람들 중 하나입니다. 왜 여기 머무르는지 모르겠지만,"
rows["373:1389999407"]="다시 만나서 반갑네요$B$B스톰하트 왕은 잠시 동안 떠나고 있다고 알려줬는데... 그에게 돌아온 슬픈 기억은...$B$B그 동안 우리 부족의 책임을 맡았어요."
rows["373:241604107"]="우리는 앞에 보이는 굴을 시간의 길이라고 부른답니다. 시간의 길의 수는 무한하지요. 주인님께서는 현재 당신의 현실에서 존재하고 있는 시간의 길을 '문제가 있는 지역'이라고 간주하셨습니다. 이런 지역은 주제는 전혀 다를지 몰라도 그 원인은 언제나 하나랍니다. 다시 말해 동일한 세속적 혼란으로 인해 존재하게 되었다는 뜻입니다. 시간의 길 안을 여행할 땐 이 사실을 명심하십시오..."
rows["373:277339464"]="마지막 죽었던 사람이었고, 필사적인 상자가 내 영혼이 빠져나가는 것을 느꼈을 때,$B$B<토레스 왕자 머리 흔들린다>$B$B이 땅과 나 사이에 조약이 맺혔습니다. 이 세상으로 내 피가 흘려요.$B$B저는 로레스 아란의 용 라이더들의 이야기는 시간의 흐름에 빠지지 않았다는 것을 확신할 때까지 쉬지 않을 것입니다.\010"
rows["373:352800849"]="넌... 뭐?$B$B여기 와서 그렇게 말해!$B$B<크리스토프가 발자국하고  ⁇ 을 때리고 화를 내며 머리를 뒤집어 당신을 바라보고 있습니다.>$B$B그래서 도와줘, 난 네 머리를  ⁇ 어 버릴 거야! 나는 내 부츠로 남은 빈 구멍을 채우겠다! 여기 와!$B$B<크리스토프가 네 목을 잡으려고 노력하고, 손가락이 얼굴에서 몇 인치 떨어진 곳에 휘어지는 것>"
rows["374:1897092036"]="곧 먹을 걸 찾아야 할 거 같아 얼라이언스 고기하고 있는 것 같아서 $2092w 이 중 $2093w 무지개 깃털 알바코어가 포장되어 있습니다. $2098w 이 중 $2099w 굽은 랩토르 및 $2101w 이 중 $2103w 얼룩진 노란색 꼬리들이 준비되어 현재 냉장고로 보관되어 있으며, 시리투스 센라리온 포지션으로 운송을 기다리고 있습니다."
rows["375:1223064779"]="칼과 모그라인은 독자적인 존재였죠. 이 행위는 칼을 손상시켰고, 켈'투자드의 죽음의 기사로서 모그라인의 자신의 부패로 이어졌다고 말씀드렸습니다. 만약 살아간다면, 이 끔찍한 범죄를 저지른 사람들을 폭로하겠다고 맹세했습니다. 두일 동안 저는 스컬지의 부패와 전염 아래 머물렀습니다.\010"
rows["375:291005734"]="부티 베이에는 남해에서 가장 좋은 클램  ⁇ 이 있습니다. 요리에 관심이 없습니다. 그럼 내가 먼저 당신을 환영 할 수 있습니다. 마이든스 펀시, 동부 왕국과 칼림도어 사이 여행하는 가장 훌륭한 여객 배. 그녀는 곧 다시 라치에 여행 할 예정입니다. 그래서 그녀가 도착할 때까지 편안하게하십시오."
rows["375:341354265"]="한 번만? 한 번만? 농담을 하겠군요. 곰 엉덩이가 모을 수 없나요? 아마 제가 뽑을 수 있는 희귀한 꽃이 있는데요. 그 꽃을 약간 환각성 토닉으로 만들게 되죠. 그 후에 여러분은 마셔도 되죠. 그 결과 큰 종말의 비전을 보게 되죠."
rows["376:1280879664"]="블랙록 오크는 내 친척이야 내 아버지는 블랙록이었고 그의 아버지는 그 이전과 마찬가지로$b$b하지만 다른 모든 것 보다 먼저, 저는 오크입니다.$b$b내 고왕이 내 일을 완수할 수 있도록 허락해줬고 블랙록 오크들이 그들의 잘못을 배우기 전까지는 떠나지 않을거야"
rows["376:162974386"]="당신이 우리에게 제공한 독소의 샘플에 따르면, 우리는 다음과 같은 것을 필요로 할 것이라고 생각합니다. 미묘한 가속기, 4 개의 외형성 공명기, 그리고 4 개의 루네클레트.$B$B일단 이 물건들을 가지고 나면, 당신은 카운터 에이전트를 그  ⁇ 에 넣을 수 있어야 합니다."
rows["376:1760101044"]="트롤bane 혈통의 영웅성은 전설적인 것입니다.$B$B그리고 그를 살아 있는 곳에서 발견하기 위해서 아웃랜드...$B$B<로무스는 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너 너$B$B그 를 처음 보고자, 거의 의식을 잃었습니다. 충격 은 압도적 이었습니다. 그 의 앞 에 무릎을 꿇고 눈물 을 흘리면서 싸워야 했습니다.$B$B로타르의 아들들이 안전해지도록 최선을 다할 거라고 내 귀여운 뒤에서 내걸 수 있습니다."
rows["376:763437336"]="내 옆에 무릎 꿇고, 친구.$B$B<건은 진통으로 지위를 바꾸려고 애쓰고 있습니다. 왼쪽 손은 상처를 붙잡고 있습니다.$B$B왜성들이 처음 침입했을 때 불모의 땅저는 그들의 기구를 망치고, 그들의 굴을 해치며만 만족했습니다."
rows["377:1898436675"]="블랙스미스? 아니, 우리의 마지막은 다시 그 어리석은 스컬지 중 하나가되었습니다. 마을 남쪽에 있는 언더시티에도 있습니다. 언더시티는 로데론의 유적 아래 있습니다. 똑똑한 이름, 아? 그냥 유적 뒤에 엘리베이터를 내려가십시오. 그러면 당신은 언더시티 경호자 중 한 명과 이야기 할 수 있습니다. 그들은 당신을 올바른 방향으로 지목 할 수 있어야합니다."
rows["377:2024916818"]="당신이 우리에게 제공한 독소의 샘플에 따르면, 우리는 다음과 같은 것을 필요로 할 것이라고 생각합니다. 미묘한 가속기, 5 개의 소마틱 강화기, 그리고 4 개의 론클레인.$B$B일단 이 물건들을 가지고 나면, 당신은 카운터 에이전트를 그  ⁇ 에 넣을 수 있어야 합니다."
rows["377:2087514885"]="하위 도시 대표로서 오시엔도온이 그림자 협의회로부터 해방되어야 한다는 주장을 제기하고자 합니다. 즉, 우리가 미래에 대한 희망을 가질 수 있고$B$B우리 민족들은 이미 너무 많이 고통받았어요."
rows["377:2125424391"]="맥주와 소시지 옆에 브루페스트의 가장 인기있는 부분은 기념품입니다. 전통적인 휴가 의복에서 맛있는 맥주 미니 케그까지, 벨비 퀴즈 스위치에서 모든 종류의 브루페스트 주제 아이템이 제공됩니다. 브루페스트 상권만 손에 넣을 수 있도록 하십시오. 그것은 그들을 구입하는 유일한 방법이기 때문에! 당신은 브루페스트 경기장에서 도움을 통해 상권을 얻을 수 있습니다."
rows["377:365421837"]="틸러스는 당신을 보석으로 장식하거나 전쟁에 대비하지 않을 겁니다.$B$B농사는 조금 다른 일입니다.$B$B더 느린 인생이지만 좋은 삶이야, 도카에게 물어봐도 도카는 알잖아$B$B농장을 짓고, 작물을 심고, 자란 음식을 즐겨 먹어도 되죠.$B$B흥미롭다면 하프힐로 가서 직접 보셔야 합니다!"
rows["377:559601888"]="아, 그래, 우리 공격 호드 타우라조 시. 그 결정의 영향에 대해 고민했습니다.$B$B타우라조는 '무소 한 목표'라고 할 수 있는 곳이었는데, 주로 사냥꾼 들 의 수용소 였지만, 그 는 수 년 동안 호드 보병 을 모집 하고, 장비를 갖추고 훈련 시키기 위해 사용 되었다.$B$B스카우들이 타우라조의 가장 위험한 부대가 사냥을 하고 있다고 보고했을 때 우리는 빨리 행동해야 했습니다."
rows["378:1108831390"]="저주받은 자들의 숭배는 그 범위가 커졌다. 수도에서부터 호드와 얼라이언스의 작은 마을과 하 ?? 들까지 거의 모든 도시에는 그들의 시민들 사이에서 비밀리에 종속된 종족들이 있다.$B$B너무 놀라지 마세요. 신종은 의식과 의식에 유니폼을 입습니다. 당신은 모험 중에 한 사람과 상호작용했을 가능성이 매우 높습니다."
rows["379:1785267851"]="<복지판과  ⁇ 에 붙은 흙 조각이 있는 거대한 책. 유온이 전통을 이어오고 이 저널에서 선송 랜치의 역사를 기록하고 있는 것 같다.$B$B\"내 가족 의 땅 을 이전 영광 으로 회복 한 것 은 고맙습니다. 더 큰 일 들 을 하고 있습니다. 이제 이 페이지를 채우는 차례 가 당신 이 있습니다\"."
rows["37:1005722620"]="영웅들, 너랑는 살아 있어"
rows["37:1013381933"]="불타는 스텝 - 일곱 사람 의 표지판"
rows["37:10139276"]="%s는 '테러리징 스크릭'을 출연한다."
rows["37:1016834872"]="네, 부터랑의 힘을 느껴봐!"
rows["37:1017333085"]="때가 왔다! 한 놈도 살려두지 마라!"
rows["37:101763569"]="노인 틸의 이야기를 들려줘"
rows["37:1019216882"]="당신이 원하는 것을 할 수 있습니다."
rows["37:1020573536"]="Sir, 다른 비행기 필요해요"
rows["37:1021018496"]="얘기할 시간이 없어, 할 일이 있어!"
rows["37:102168323"]="왜 내가 그렇게 주문해야 할까요?"
rows["37:1025437136"]="뭔가 마음에 걸리시는 거지요?"
rows["37:1026126854"]="네, 우리 방식대로 처리해 줄게"
rows["37:1027066686"]="우리는 이 세상에서 모든 시간을 가지고 있습니다..."
rows["37:103084310"]="시민님, 안내가 필요해요?"
rows["37:1033116672"]="그래, 장로님, 책에 대해 더 말해 주세요."
rows["37:1033144775"]="가루바시가 우리의 땅을 되찾아갈 거야"
rows["37:1034377585"]="그리고 내가 훔쳐주길 바라니?"
rows["37:1035149097"]="너무 강하네... 싸울 수 없어"
rows["37:1038074845"]="네 영혼은 영원히 이곳을 헤매리라!"
rows["37:103884922"]="%s 몇 번이나 화면에 파운드를 올려놓았어요."
rows["37:1046760461"]="저쪽, 내 감옥관을 죽여라!"
rows["37:1047517757"]="실크농업은 위험한 사업입니다."
rows["37:1054652323"]="너무 추워서, 너무 허약하고 무살했어요"
rows["37:105513089"]="다음 정류장인 무덤"
rows["37:1056604928"]="또 다른 장난감을 가져와 발사해"
rows["37:1056957698"]="냄새가 나고, 공포의 냄새가 난다"
rows["37:1058239237"]="그의 가르침이 틀리다고 생각하십니까?"
rows["37:1059179777"]="비극이로군. 그 먼 길을 왔건만 패배하다니."
rows["37:1063700656"]="우리가 정말 고향으로 돌아갈 수 있을까요?"
rows["37:1067000072"]="내 주군은 어디 있지? 내 로물로는 어디에?"
rows["37:106725737"]="명예의 계곡은 확보됐어!"
rows["37:1069006111"]="서로 덮고, 서 있어!"
rows["37:1070202659"]="하늘로부터 이 혐오스러운 것을 날려버리자!"
rows["37:1071658824"]="너로 해방됐어!"
rows["37:1072159677"]="우리 세상은 당신 같은 영웅이 더 필요해"
rows["37:1072241334"]="행운이 있으세요. 그 벨을 찾으면 좋겠습니다."
rows["37:1075473445"]="대신 스톤스킨 토템을 받을 수 있나요?"
rows["37:1077088493"]="오프닝이 보이네요!"
rows["37:1077913319"]="우리는 원자들에 대한 도움을 요청하지 않습니다."
rows["37:1080150294"]="멀리 떨어져 있어!"
rows["37:1081511440"]="그 뒤에 동굴이 있는지 궁금합니다."
rows["37:1081966335"]="꽉 붙잡으십시오. 재빠르게 임무를 완수해야지요."
rows["37:1091101235"]="물품에 대한 작은 수수료가 요구됩니다."
rows["37:1093722311"]="%s 실망으로 머리를 흔들고"
rows["37:1096405036"]="키른라, 그녀는 팬더를 좋아해요  "
rows["37:1106721607"]="앞으로! 핏빛안개 섬의 야생이 기다리고 있다!"
rows["37:1107676563"]="내가 좀 도와줄게"
rows["37:1110841120"]="잠수함은 폭발할 거야!"
